('MPM2D', 'analytic-geometry', 'classifying-shapes', 9, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(4, 0), C(4, 3), and D(0, 3). Using slopes, what shape is ABCD?', 2,
 '[{"text": "Trapezoid", "feedback": "Both pairs of opposite sides turn out parallel here, not just one — check the slope of AD and BC as well as AB and DC."}, {"text": "Parallelogram (not a rectangle)", "feedback": "Check the slopes of adjacent sides, like AB and AD — a slope of 0 next to a vertical (undefined) slope always meets at a right angle."}, {"text": "Rectangle", "feedback": "Correct. AB and DC are both horizontal (slope 0), AD and BC are both vertical (undefined slope), and horizontal meeting vertical always gives right angles."}, {"text": "Kite", "feedback": "A kite has two pairs of adjacent (not opposite) sides equal, with no sides parallel — but here both pairs of opposite sides are parallel."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 10, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(5, 0), C(8, 4), and D(3, 4). Using slopes, what shape is ABCD?', 0,
 '[{"text": "Parallelogram (not a rectangle)", "feedback": "Correct. Slope of AB = slope of DC = 0, and slope of AD = slope of BC = 4/3 — both pairs of opposite sides are parallel, but 0 and 4/3 don''t multiply to −1, so it isn''t a rectangle."}, {"text": "Rectangle", "feedback": "Check whether adjacent sides are perpendicular — the slopes 0 and 4/3 don''t multiply to −1, so there are no right angles here."}, {"text": "Trapezoid", "feedback": "A trapezoid has only one pair of parallel sides — check the slope of AD and BC as well as AB and DC."}, {"text": "Not a special quadrilateral", "feedback": "Both pairs of opposite sides actually do turn out parallel here, which is more than a general quadrilateral guarantees."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 11, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(6, 0), C(4, 3), and D(1, 3). Using slopes, what shape is ABCD?', 3,
 '[{"text": "Parallelogram", "feedback": "Check the slope of AD against BC — they come out different, so only one pair of opposite sides is actually parallel."}, {"text": "Rectangle", "feedback": "A rectangle needs both pairs of sides parallel and adjacent sides perpendicular — here, only one pair of sides is even parallel."}, {"text": "Kite", "feedback": "A kite has two pairs of adjacent sides equal, with no sides parallel — but here, AB and DC actually are parallel."}, {"text": "Trapezoid", "feedback": "Correct. Slope of AB = slope of DC = 0, so that pair is parallel, but slope of AD (3) and BC (−1.5) are different — with only one pair of parallel sides, this is a trapezoid."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 12, 'Medium',
 'Quadrilateral ABCD has A(0, 0), B(3, 1), C(5, 5), and D(1, 3). Is ABCD a parallelogram?', 1,
 '[{"text": "Yes, since AB is parallel to DC", "feedback": "Recompute both slopes: AB has slope 1/3 and DC has slope 1/2 — these are different, so this pair of sides is not parallel."}, {"text": "No, neither pair of opposite sides is parallel", "feedback": "Correct. Slope of AB (1/3) ≠ slope of DC (1/2), and slope of AD (3) ≠ slope of BC (2) — with neither pair of opposite sides parallel, this isn''t a parallelogram."}, {"text": "Yes, since AD is parallel to BC", "feedback": "Recompute both slopes: AD has slope 3 and BC has slope 2 — these are different, so this pair of sides is not parallel either."}, {"text": "Yes, all four sides are parallel to each other", "feedback": "No two sides here share a slope — recompute all four slopes and compare them in opposite pairs."}]'::jsonb,
 'quadrilateral-classification-slopes'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 13, 'Challenge',
 'Triangle ABC has A(1, 2), B(4, 6), and C(9, 4). Using the distance formula on all three sides, classify the triangle.', 2,
 '[{"text": "Isosceles", "feedback": "Recompute all three squared side lengths: AB²=25, BC²=29, AC²=68 — none of these match, so no two sides are equal."}, {"text": "Right", "feedback": "Check whether any two of the squared side lengths (25, 29, 68) add up to the third — none of the three combinations work out."}, {"text": "Scalene", "feedback": "Correct. AB² = 3²+4² = 25, BC² = 5²+2² = 29, and AC² = 8²+2² = 68 — all three are different, so no two sides are equal, making this triangle scalene."}, {"text": "Equilateral", "feedback": "All three squared side lengths (25, 29, 68) are different — equilateral needs all three sides to be exactly equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 14, 'Challenge',
 'Triangle ABC has A(0, 0), B(4, 3), and C(8, 0). Using the distance formula on all three sides, classify the triangle.', 1,
 '[{"text": "Scalene", "feedback": "Recompute all three squared side lengths: AB²=25, BC²=25, AC²=64 — two of these actually match."}, {"text": "Isosceles (but not right)", "feedback": "Correct. AB² = 4²+3² = 25 and BC² = 4²+3² = 25 are equal (isosceles), but AB² + AC² = 25 + 64 = 89 ≠ BC² = 25 and no other combination matches either, so there''s no right angle."}, {"text": "Right (but not isosceles)", "feedback": "Two of the three squared side lengths (AB²=25 and BC²=25) actually are equal, which does make this triangle isosceles — but check whether any two lengths add to the third; none do, so there''s no right angle."}, {"text": "Equilateral", "feedback": "AC² = 64, which doesn''t match AB² or BC² (both 25) — equilateral needs all three sides equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 15, 'Challenge',
 'Triangle ABC has A(0, 0), B(5, 0), and C(0, 12). Using the distance formula on all three sides, classify the triangle.', 3,
 '[{"text": "Isosceles right triangle", "feedback": "Check the three squared side lengths (25, 169, 144) carefully — none of them match each other, so this triangle isn''t isosceles."}, {"text": "Equilateral", "feedback": "The three squared side lengths (25, 169, 144) are all different — equilateral needs all three sides exactly equal."}, {"text": "Scalene, with no right angle", "feedback": "Check whether any two of the squared side lengths add up to the third: 25 + 144 = 169 — that condition is actually satisfied."}, {"text": "Scalene right triangle", "feedback": "Correct. AB²=25, AC²=144, BC²=169, and all three are different (scalene); since AB² + AC² = 25+144 = 169 = BC², there''s also a right angle at A."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 16, 'Challenge',
 'Triangle ABC has A(2, 1), B(2, 7), and C(8, 1). Using the distance formula on all three sides, classify the triangle.', 0,
 '[{"text": "Isosceles right triangle", "feedback": "Correct. AB²=36 and AC²=36 are equal (isosceles), and AB² + AC² = 36+36 = 72 = BC², so there''s also a right angle at A."}, {"text": "Scalene right triangle", "feedback": "Two of the three squared side lengths (AB²=36 and AC²=36) actually come out equal — recheck whether all three sides are really different."}, {"text": "Isosceles, but not right", "feedback": "Check whether any two of the squared side lengths add up to the third: 36 + 36 = 72, which matches BC² exactly."}, {"text": "Equilateral", "feedback": "BC² = 72, which doesn''t match AB² or AC² (both 36) — equilateral needs all three sides exactly equal."}]'::jsonb,
 'triangle-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 17, 'Advanced',
 'Quadrilateral ABCD has A(0, 0), B(3, 4), C(0, 8), and D(-3, 4). Using both side lengths and diagonal lengths, what is the most precise name for this shape?', 2,
 '[{"text": "Square", "feedback": "All four sides are equal (a rhombus), but check the two diagonals, AC and BD — they come out to different lengths, which rules out a square."}, {"text": "Parallelogram (but not a rhombus)", "feedback": "All four sides actually come out equal here (each measuring 5), which is a stronger result than a general parallelogram guarantees."}, {"text": "Rhombus (but not a square)", "feedback": "Correct. Every side measures √(3²+4²) = 5, making this a rhombus, but the diagonals AC = 8 and BD = 6 are different lengths — a square needs equal diagonals, so this rhombus isn''t a square."}, {"text": "Rectangle", "feedback": "A rectangle needs right angles but not necessarily equal sides — here all four sides are actually equal, which points toward a rhombus instead."}]'::jsonb,
 'quadrilateral-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 18, 'Advanced',
 'Quadrilateral ABCD has A(0, 0), B(3, 2), C(6, 0), and D(3, -5). What is the most precise name for this shape?', 1,
 '[{"text": "Rhombus", "feedback": "Check all four side lengths — AB and BC match each other, and CD and DA match each other, but the two pairs aren''t equal to each other."}, {"text": "Kite", "feedback": "Correct. AB = BC = √13 (one pair of adjacent sides) and CD = DA = √34 (the other pair of adjacent sides), with the two pairs unequal to each other — exactly the definition of a kite."}, {"text": "Parallelogram", "feedback": "Check the slopes of opposite sides, like AB and DC — a parallelogram needs both pairs of opposite sides parallel, which isn''t the case here."}, {"text": "Trapezoid", "feedback": "Check the slopes of both pairs of opposite sides — neither pair here turns out to be parallel."}]'::jsonb,
 'quadrilateral-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 19, 'Advanced',
 'Quadrilateral ABCD has A(0, 0), B(5, 1), C(7, 6), and D(1, 4). What is the most precise name for this shape?', 3,
 '[{"text": "Parallelogram", "feedback": "Check the slopes of AB versus DC, and AD versus BC — neither pair of opposite sides turns out to share a slope."}, {"text": "Kite", "feedback": "A kite needs two distinct pairs of adjacent sides to be equal in length — check all four side lengths here; none of them match another."}, {"text": "Trapezoid", "feedback": "Check the slopes of both pairs of opposite sides carefully — neither pair here is actually parallel."}, {"text": "A general quadrilateral (none of the above)", "feedback": "Correct. All four side lengths are different, and neither pair of opposite sides is parallel — this shape doesn''t fit any of the special quadrilateral categories."}]'::jsonb,
 'quadrilateral-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'classifying-shapes', 20, 'Advanced',
 'Quadrilateral ABCD has A(0, 0), B(4, 3), C(-2, 11), and D(-6, 8). Using both slope and side length, what is the most precise name for this shape?', 1,
 '[{"text": "Square", "feedback": "The sides here alternate between two different lengths (5 and 10), which rules out a square — a square needs all four sides equal."}, {"text": "Rectangle (but not a square)", "feedback": "Correct. AB and CD both measure 5, BC and DA both measure 10 (opposite sides equal), and the direction vectors of AB (4,3) and BC (−6,8) are perpendicular (their dot product is 4×−6 + 3×8 = 0) — right angles with unequal adjacent sides make this a rectangle, not a square."}, {"text": "Rhombus", "feedback": "The four sides here aren''t all equal — they alternate between lengths of 5 and 10, which rules out a rhombus."}, {"text": "Parallelogram (but not a rectangle)", "feedback": "Check the angle between adjacent sides AB and BC — their direction vectors are perpendicular, which is a stronger result than a general parallelogram guarantees."}]'::jsonb,
 'quadrilateral-classification-multi-step'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 5, 'Easy',
 'To verify that two sides of a triangle are parallel, which formula should you apply?', 2,
 '[{"text": "The distance formula", "feedback": "The distance formula measures a side''s length — it doesn''t tell you anything about the direction two sides point in."}, {"text": "The midpoint formula", "feedback": "The midpoint formula finds a point halfway between two others — it says nothing about whether two sides run in the same direction."}, {"text": "The slope formula", "feedback": "Correct. Parallel lines share the exact same slope, so calculating and comparing the slopes of the two sides is exactly the right tool."}, {"text": "The quadratic formula", "feedback": "The quadratic formula solves equations of the form ax²+bx+c=0 — it has no role in this kind of coordinate geometry check."}]'::jsonb,
 'verification-tool-choice'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 6, 'Easy',
 'To verify that a quadrilateral has a right angle at one vertex, which formula should you apply to the two sides meeting there?', 1,
 '[{"text": "The midpoint formula", "feedback": "The midpoint formula finds a point halfway between two others — it doesn''t measure the angle between two sides."}, {"text": "The slope formula", "feedback": "Correct. Two sides are perpendicular (forming a right angle) exactly when the product of their slopes is −1, so the slope formula is the tool to use."}, {"text": "The distance formula", "feedback": "The distance formula measures length — it can help classify a triangle by its side lengths, but it doesn''t test for a right angle on its own."}, {"text": "The discriminant", "feedback": "The discriminant (b²−4ac) tells you about the roots of a quadratic equation — it has no role in this kind of geometric verification."}]'::jsonb,
 'verification-tool-choice'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 7, 'Easy',
 'To verify that a rectangle''s two diagonals are equal in length, which formula should you apply to each diagonal?', 3,
 '[{"text": "The slope formula", "feedback": "Slope tells you the direction of a line segment, not how long it is — length needs a different formula."}, {"text": "The midpoint formula", "feedback": "The midpoint formula finds where a diagonal''s centre point is — it doesn''t measure the diagonal''s length."}, {"text": "The quadratic formula", "feedback": "The quadratic formula solves equations of the form ax²+bx+c=0 — it has no role in measuring a segment''s length."}, {"text": "The distance formula", "feedback": "Correct. The distance formula measures the length of a segment from its endpoints, which is exactly what''s needed to compare the two diagonals."}]'::jsonb,
 'verification-tool-choice'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 8, 'Easy',
 'A point is claimed to be exactly halfway between two other points. Which formula would you use to check this?', 0,
 '[{"text": "The midpoint formula", "feedback": "Correct. The midpoint formula computes the exact point halfway between two others, so comparing its result to the claimed point checks this directly."}, {"text": "The slope formula", "feedback": "Slope describes a line''s steepness — it doesn''t identify a specific point along a segment."}, {"text": "The distance formula", "feedback": "The distance formula alone gives a segment''s length; you''d need to compare two distances to check a midpoint, which the midpoint formula does directly."}, {"text": "The discriminant", "feedback": "The discriminant (b²−4ac) is used to analyze the roots of a quadratic equation, not to locate a point on a segment."}]'::jsonb,
 'verification-tool-choice'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 9, 'Medium',
 'Triangle ABC has A(0, 0), B(0, 5), and C(3, 0). At which vertex is the right angle?', 0,
 '[{"text": "A", "feedback": "Correct. AB is vertical (x = 0 throughout, undefined slope) and AC is horizontal (y = 0 throughout, slope 0) — a vertical side meeting a horizontal side always forms a right angle, here at A."}, {"text": "B", "feedback": "Sides AB and BC meet at B. AB is vertical (undefined slope), but BC has slope (0−5)÷(3−0) = −5/3 — that doesn''t pair with a vertical side to form a right angle."}, {"text": "C", "feedback": "Sides BC and AC meet at C. AC is horizontal (slope 0), but BC has slope −5/3 — that doesn''t pair with a horizontal side to form a right angle."}, {"text": "There is no right angle", "feedback": "Two of this triangle''s sides are exactly vertical and horizontal, which always meet at a right angle — look again at which vertex that happens at."}]'::jsonb,
 'right-angle-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 10, 'Medium',
 'Rectangle ABCD has A(0, 0), B(4, 0), C(4, 3), and D(0, 3). Verify its diagonals are equal by finding the length of each.', 1,
 '[{"text": "AC = 4, BD = 3", "feedback": "These are just the rectangle''s own side lengths, not the diagonals — apply the distance formula between A and C, and between B and D."}, {"text": "AC = BD = 5", "feedback": "Correct. AC = √(4²+3²) = 5, and BD = √((0−4)²+(3−0)²) = 5 — confirming a rectangle''s diagonals are always equal."}, {"text": "AC = 5, BD = 7", "feedback": "Recompute BD using the distance formula on B(4,0) and D(0,3) — it comes out equal to AC, not longer."}, {"text": "AC = 25, BD = 25", "feedback": "These are the diagonals'' squared lengths (the value under the square root), not the diagonals themselves — one more step is needed."}]'::jsonb,
 'diagonal-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 11, 'Medium',
 'A point (5, 3) is claimed to be the midpoint of A(2, 3) and B(8, 3). Verify this by checking that it''s equidistant from A and B.', 2,
 '[{"text": "Distance to A is 2, distance to B is 4 — not equidistant", "feedback": "Recompute both distances using the distance formula on (5,3) with A(2,3) and with B(8,3) — they actually come out equal."}, {"text": "Distance to A is 5, distance to B is 3 — not equidistant", "feedback": "This reuses the point''s own coordinates as if they were the distances — apply the distance formula to (5,3)–A and (5,3)–B instead."}, {"text": "Distance to A is 3, distance to B is 3 — equidistant, confirming the midpoint", "feedback": "Correct. The distance from (5,3) to A(2,3) is 3, and the distance from (5,3) to B(8,3) is also 3 — being equidistant from both endpoints confirms it''s the midpoint."}, {"text": "Distance to A is 6, distance to B is 6 — equidistant, confirming the midpoint", "feedback": "The distances are actually equal (confirming the midpoint), but recompute their value — each one comes out to 3, not 6."}]'::jsonb,
 'midpoint-verification-via-distance'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 12, 'Medium',
 'Is segment AB parallel to segment CD, where A(1, 2), B(4, 8), C(0, 5), and D(2, 9)?', 0,
 '[{"text": "Yes, both have slope 2", "feedback": "Correct. Slope of AB = (8−2)÷(4−1) = 2, and slope of CD = (9−5)÷(2−0) = 2 — equal slopes confirm the two segments are parallel."}, {"text": "No, AB has slope 2 and CD has slope 4", "feedback": "Recompute the slope of CD using (9−5)÷(2−0) — it comes out to 2, the same as AB, not 4."}, {"text": "Yes, both pass through the origin", "feedback": "Neither segment actually passes through (0,0) — and even if they did, that wouldn''t be the test for parallel lines anyway."}, {"text": "No, they have different y-intercepts", "feedback": "Different y-intercepts alone don''t rule out parallel — two lines are parallel exactly when their slopes match, regardless of their intercepts."}]'::jsonb,
 'parallel-verification-via-slope'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 13, 'Challenge',
 'Quadrilateral ABCD has A(0, 0), B(6, 2), C(10, 8), and D(4, 6). Verify it''s a parallelogram by finding the midpoint of each diagonal. What is the shared midpoint?', 1,
 '[{"text": "(5, 3)", "feedback": "Recompute the midpoint of diagonal BD using B(6,2) and D(4,6) — this doesn''t match what that gives."}, {"text": "(5, 4)", "feedback": "Correct. The midpoint of AC is ((0+10)÷2, (0+8)÷2) = (5, 4), and the midpoint of BD is ((6+4)÷2, (2+6)÷2) = (5, 4) — the same point, confirming the diagonals bisect each other."}, {"text": "(8, 5)", "feedback": "This doesn''t match the midpoint of either diagonal — recompute using the actual coordinates of A, C and of B, D."}, {"text": "(10, 8)", "feedback": "This is just vertex C''s own coordinates, not the midpoint of a diagonal."}]'::jsonb,
 'parallelogram-diagonal-midpoint'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 14, 'Challenge',
 'Verify that P(4, 3) is equidistant from A(0, 0) and B(8, 0) by finding both distances.', 0,
 '[{"text": "PA = PB = 5", "feedback": "Correct. PA = √(4²+3²) = 5, and PB = √((8−4)²+3²) = 5 — since both distances are equal, P is equidistant from A and B (in fact, it lies on their perpendicular bisector)."}, {"text": "PA = 4, PB = 3", "feedback": "This reuses the point''s own coordinates instead of applying the distance formula to PA and PB."}, {"text": "PA = 5, PB = 7", "feedback": "Recompute PB using the distance formula on P(4,3) and B(8,0) — it comes out equal to PA, not longer."}, {"text": "PA = 25, PB = 25", "feedback": "These are the squared distances (the value under the root), not the distances themselves — one more step is needed."}]'::jsonb,
 'equidistant-point-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 15, 'Challenge',
 'Triangle ABC has A(0, 0), B(10, 0), and C(4, 6). M and N are the midpoints of AC and BC. Verify the midsegment theorem by finding the length of MN.', 2,
 '[{"text": "10", "feedback": "That''s the length of AB, the side MN is parallel to — the midsegment itself is shorter, not equal to it."}, {"text": "2.5", "feedback": "This is a quarter of AB rather than half — the midsegment theorem states MN is exactly half of the side it''s parallel to."}, {"text": "5", "feedback": "Correct. M = (2, 3) and N = (7, 3), so MN = √((7−2)² + 0²) = 5 — exactly half of AB''s length of 10, as the midsegment theorem predicts."}, {"text": "7", "feedback": "This doesn''t match either the midpoints'' distance apart or half of AB — recompute M and N first, then the distance between them."}]'::jsonb,
 'midsegment-theorem'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 16, 'Challenge',
 'Rhombus ABCD has A(0, 0), B(3, 4), C(7, 1), and D(4, -3). Verify its diagonals are perpendicular by finding both slopes.', 3,
 '[{"text": "Slope of AC = 1/7, slope of BD = 7, product = 1", "feedback": "Recheck the sign of BD''s slope — using B(3,4) and D(4,−3), the rise is negative, so the slope should come out negative, not positive."}, {"text": "Slope of AC = 7, slope of BD = −1/7, product = −1", "feedback": "The two slopes have been swapped between the diagonals — recompute each one using its own pair of endpoints."}, {"text": "Slope of AC = 1/7, slope of BD = −1/7, product = −1/49", "feedback": "Recheck the slope of BD using B(3,4) and D(4,−3) — the rise and run don''t give this value."}, {"text": "Slope of AC = 1/7, slope of BD = −7, product = −1", "feedback": "Correct. Slope of AC = (1−0)÷(7−0) = 1/7, slope of BD = (−3−4)÷(4−3) = −7, and (1/7)×(−7) = −1, confirming the diagonals are perpendicular."}]'::jsonb,
 'perpendicular-diagonals-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 17, 'Advanced',
 'Rectangle ABCD has A(0, 0), B(8, 0), C(8, 3), and D(0, 3). Verify that its diagonals are equal by finding each length, to one decimal place.', 0,
 '[{"text": "AC = BD = 8.5", "feedback": "Correct. AC = √(8²+3²) = √73 ≈ 8.5, and BD = √((0−8)²+(3−0)²) = √73 ≈ 8.5 — confirming a rectangle''s diagonals are always equal."}, {"text": "AC = 8.5, BD = 7.8", "feedback": "Recompute BD using B(8,0) and D(0,3) in the distance formula — it comes out to the same value as AC."}, {"text": "AC = 11.0, BD = 11.0", "feedback": "This adds the two side lengths (8 and 3) instead of applying the distance formula to the diagonal."}, {"text": "AC = 73.0, BD = 73.0", "feedback": "This is 8² + 3², the value under the square root sign — one more step (taking the root) is still needed."}]'::jsonb,
 'diagonal-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 18, 'Advanced',
 'Quadrilateral ABCD has A(0, 0), B(4, 0), C(6, 3), and D(2, 3). Verify it''s a parallelogram using midpoints, then determine whether it''s also a rectangle.', 1,
 '[{"text": "It''s a parallelogram and a rectangle, since both diagonals share the midpoint (3, 1.5)", "feedback": "The shared midpoint (3, 1.5) does confirm it''s a parallelogram, but that alone doesn''t confirm right angles — check the slopes of adjacent sides too."}, {"text": "It''s a parallelogram but not a rectangle, since AB and AD aren''t perpendicular", "feedback": "Correct. Both diagonals share midpoint (3, 1.5), confirming a parallelogram, but slope of AB (0) times slope of AD (1.5) gives 0, not −1 — so the sides aren''t perpendicular, and it isn''t a rectangle."}, {"text": "It isn''t a parallelogram, since the diagonals have different midpoints", "feedback": "Recompute both midpoints: AC gives (3, 1.5) and BD gives (3, 1.5) as well — they''re actually the same point."}, {"text": "It''s a rectangle but not a parallelogram", "feedback": "Every rectangle is itself a parallelogram — these two categories aren''t mutually exclusive."}]'::jsonb,
 'parallelogram-and-rectangle-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 19, 'Advanced',
 'Trapezoid ABCD has A(0, 0), B(6, 0), C(5, 4), and D(1, 4). Verify it''s an isosceles trapezoid by checking that AB is parallel to DC, and that the two legs (AD and BC) are equal in length.', 3,
 '[{"text": "AB isn''t parallel to DC, so it isn''t a trapezoid at all", "feedback": "Recompute both slopes: AB and DC are both horizontal (slope 0), so this pair of sides actually is parallel."}, {"text": "AB is parallel to DC, but the legs AD ≈ 4.1 and BC ≈ 3.6 are unequal", "feedback": "Recompute BC using the distance formula on B(6,0) and C(5,4) — it comes out equal to AD, not smaller."}, {"text": "AB is parallel to DC, but the legs can''t be compared without their exact decimal values", "feedback": "Both legs simplify to the exact same expression, √17, without needing to round to decimals to compare them."}, {"text": "AB is parallel to DC (both slope 0), and the legs AD = BC = √17, confirming an isosceles trapezoid", "feedback": "Correct. AB and DC are both horizontal, and AD = √(1²+4²) = √17 while BC = √(1²+4²) = √17 as well — equal legs confirm this is an isosceles trapezoid."}]'::jsonb,
 'isosceles-trapezoid-verification'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 20, 'Advanced',
 'In parallelogram PQRS, the diagonals bisect each other at (3, 2). If P(0, 0), what are the coordinates of the opposite vertex R?', 2,
 '[{"text": "(3, 2)", "feedback": "This is the shared midpoint of the diagonals itself, not vertex R — R is as far past that midpoint as P is before it."}, {"text": "(1.5, 1)", "feedback": "This averages P and the midpoint instead of reflecting P through it — a parallelogram''s diagonal bisection point is the midpoint of P and R, not partway between them."}, {"text": "(6, 4)", "feedback": "Correct. Since the diagonals bisect each other at (3, 2), that point is the midpoint of P and R: R = (2×3 − 0, 2×2 − 0) = (6, 4)."}, {"text": "(-3, -2)", "feedback": "This reflects P through the origin instead of through the actual midpoint of the diagonals, (3, 2)."}]'::jsonb,
 'parallelogram-diagonal-bisection-solve'),
('MPM2D', 'analytic-geometry', 'verifying-properties', 21, 'Advanced',
 'Triangle ABC has A(2, 3), B(8, 3), and C(8, 11). Verify it''s right-angled using the converse of the Pythagorean theorem.', 0,
 '[{"text": "AB = 6, BC = 8, AC = 10, and 6² + 8² = 10², confirming a right angle at B", "feedback": "Correct. AB = 6, BC = 8, AC = 10, and since AB² + BC² = 36 + 64 = 100 = AC², the converse of the Pythagorean theorem confirms a right angle at B, where those two sides meet."}, {"text": "AB = 6, BC = 8, AC = 10, and 6² + 8² ≠ 10², so there''s no right angle", "feedback": "Recompute 6² + 8² and 10² separately — they actually come out equal (100 both), which does confirm a right angle."}, {"text": "AB = 8, BC = 6, AC = 10, with the right angle at A", "feedback": "AB and BC''s values are swapped, and even correctly labelled, the right angle sits at the vertex where the two legs (not the hypotenuse) meet, which is B."}, {"text": "The triangle can''t be verified this way without also knowing its angles", "feedback": "The converse of the Pythagorean theorem is exactly a way to confirm a right angle using only the three side lengths, with no angles needed."}]'::jsonb,
 'right-angle-verification-pythagorean-converse'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 5, 'Easy',
 'For the parabola y = -5x², which way does it open?', 1,
 '[{"text": "Upward", "feedback": "A negative leading coefficient makes a parabola open downward, not upward."}, {"text": "Downward", "feedback": "Correct. A negative leading coefficient (here, -5) always makes a parabola open downward."}, {"text": "To the left", "feedback": "Parabolas of the form y = ax² always open up or down, never sideways."}, {"text": "To the right", "feedback": "Parabolas of the form y = ax² always open up or down, never sideways."}]'::jsonb,
 'parabola-direction-from-sign'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 6, 'Easy',
 'Which parabola is narrower: y = 2x² or y = 7x²?', 1,
 '[{"text": "y = 2x²", "feedback": "A smaller leading coefficient makes a parabola grow more slowly, which means it''s wider, not narrower."}, {"text": "y = 7x²", "feedback": "Correct. A larger leading coefficient (7, compared to 2) makes a parabola grow faster, which pulls its arms in and makes it narrower."}, {"text": "They are the same width", "feedback": "The two coefficients, 2 and 7, are different, so the two parabolas have noticeably different widths."}, {"text": "It can''t be determined", "feedback": "The coefficient alone is enough to compare the widths of two parabolas that both open from the origin."}]'::jsonb,
 'parabola-width-comparison'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 7, 'Easy',
 'What is the vertex of the parabola y = 6x²?', 2,
 '[{"text": "(6, 0)", "feedback": "This uses the coefficient as if it were an x-coordinate — with no shift terms in the equation, the vertex stays at the origin."}, {"text": "(0, 6)", "feedback": "This uses the coefficient as if it were a y-coordinate — with no shift terms in the equation, the vertex stays at the origin."}, {"text": "(0, 0)", "feedback": "Correct. With no horizontal or vertical shift terms, y = 6x² has its vertex at the origin, (0, 0)."}, {"text": "There is no vertex", "feedback": "Every parabola has a vertex — the point where it turns around — even one as simple as y = 6x²."}]'::jsonb,
 'parabola-vertex-no-shift'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 8, 'Easy',
 'Compared to y = x², is the parabola y = 0.25x² narrower or wider?', 1,
 '[{"text": "Narrower", "feedback": "A coefficient smaller than 1 (like 0.25) makes a parabola grow more slowly than y = x², which makes it wider, not narrower."}, {"text": "Wider", "feedback": "Correct. Since 0.25 is smaller than 1, y = 0.25x² grows more slowly than y = x², making it wider."}, {"text": "The same width", "feedback": "The coefficients 0.25 and 1 are different, so the two parabolas have different widths."}, {"text": "It depends on whether x is positive or negative", "feedback": "The width comparison between two parabolas of this form doesn''t depend on which x-values you look at."}]'::jsonb,
 'parabola-width-comparison'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 9, 'Medium',
 'Which parabola is wider: y = 0.2x² or y = 3x²?', 0,
 '[{"text": "y = 0.2x²", "feedback": "Correct. A smaller |a| value (0.2, compared to 3) makes a parabola grow more slowly, which means it''s wider."}, {"text": "y = 3x²", "feedback": "A larger |a| value makes a parabola narrower, not wider — the smaller coefficient produces the wider graph."}, {"text": "They are the same width", "feedback": "The two coefficients, 0.2 and 3, are quite different in size, so the two parabolas have noticeably different widths."}, {"text": "It can''t be determined", "feedback": "The coefficient alone is enough to compare the widths of two parabolas that both open from the origin''s shape."}]'::jsonb,
 'parabola-width-comparison'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 10, 'Medium',
 'How do the graphs of y = -4x² and y = 4x² compare?', 2,
 '[{"text": "They have different widths, since one coefficient is negative", "feedback": "The width of a parabola depends on the *size* of the coefficient (|a|), not its sign — here both have |a| = 4."}, {"text": "They are completely unrelated shapes", "feedback": "Both parabolas share the same width and vertex — they''re closely related, just facing opposite directions."}, {"text": "They''re the same width, but reflections of each other across the x-axis", "feedback": "Correct. Both have |a| = 4, so they''re equally wide, but the negative sign on one flips it to open downward instead of upward — a reflection across the x-axis."}, {"text": "They''re the same width, but reflections of each other across the y-axis", "feedback": "A sign change on the leading coefficient flips a parabola vertically (across the x-axis), not sideways (across the y-axis)."}]'::jsonb,
 'parabola-sign-reflection'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 11, 'Medium',
 'If y = 2x², what is the value of y when x = 3?', 3,
 '[{"text": "6", "feedback": "This multiplies 2 and 3 directly instead of squaring x first — compute 3² before multiplying by 2."}, {"text": "9", "feedback": "This is just 3² on its own — the coefficient 2 still needs to be multiplied in."}, {"text": "12", "feedback": "Recheck: 3² = 9, and 2 × 9 should be computed, not some other combination of 2 and 3."}, {"text": "18", "feedback": "Correct. y = 2(3)² = 2(9) = 18."}]'::jsonb,
 'parabola-evaluate-at-point'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 12, 'Medium',
 'A parabola of the form y = ax² passes through the point (2, 12). Is a positive or negative, and what is its value?', 1,
 '[{"text": "Negative, a = -3", "feedback": "Since y is positive (12) and x² is always positive, a must also be positive here — recheck the sign."}, {"text": "Positive, a = 3", "feedback": "Correct. Substituting (2, 12) gives 12 = a(2)² = 4a, so a = 3 — and since a > 0, it''s positive."}, {"text": "Positive, a = 6", "feedback": "This divides 12 by 2 instead of 2² = 4 — remember x is squared before being multiplied by a."}, {"text": "Negative, a = -6", "feedback": "This divides 12 by 2 instead of 4, and also gets the sign wrong — since y is positive here, a must be positive."}]'::jsonb,
 'parabola-find-a-from-point'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 13, 'Challenge',
 'For the parabola y = -0.2x², state its direction of opening and how its width compares to y = x².', 2,
 '[{"text": "Opens upward, narrower than y = x²", "feedback": "A negative leading coefficient means this parabola opens downward, not upward."}, {"text": "Opens downward, narrower than y = x²", "feedback": "Check the size of the coefficient: |-0.2| = 0.2, which is smaller than 1 — a smaller coefficient makes a parabola wider, not narrower."}, {"text": "Opens downward, wider than y = x²", "feedback": "Correct. The negative sign means it opens downward, and since |-0.2| = 0.2 is smaller than 1, it grows more slowly than y = x², making it wider."}, {"text": "Opens upward, wider than y = x²", "feedback": "The negative sign on the coefficient means this parabola opens downward, not upward."}]'::jsonb,
 'parabola-direction-and-width'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 14, 'Challenge',
 'A parabola of the form y = ax² passes through the point (2, -8). What is the value of a?', 2,
 '[{"text": "a = 4", "feedback": "The sign is off — since y is negative here (-8) while x² is always positive, a must be negative too."}, {"text": "a = -4", "feedback": "This divides -8 by 2 instead of 2² = 4 — remember x is squared before being multiplied by a."}, {"text": "a = -2", "feedback": "Correct. Substituting (2, -8) gives -8 = a(2)² = 4a, so a = -8 ÷ 4 = -2."}, {"text": "a = 2", "feedback": "The sign is off — since y is negative here (-8), a must also come out negative."}]'::jsonb,
 'parabola-find-a-from-point'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 15, 'Challenge',
 'Two parabolas, y = ax² and y = bx², both pass through the point (2, 8). What must be true?', 0,
 '[{"text": "a = b = 2", "feedback": "Correct. Substituting (2, 8) into either equation gives 8 = 4a (or 4b), so both a and b must equal 2 — meaning the two parabolas are actually identical."}, {"text": "a and b must be different, since they''re different letters", "feedback": "Using different letters doesn''t force different values — solving the equation shows both must equal exactly 2."}, {"text": "a + b = 8", "feedback": "Substituting (2,8) into y = ax² gives 8 = 4a, an equation about a alone (and separately about b) — not a combined sum like this."}, {"text": "There isn''t enough information to know a or b", "feedback": "Substituting the point (2, 8) into y = ax² gives exactly one equation, 8 = 4a, which pins down a (and, the same way, b) precisely."}]'::jsonb,
 'parabola-same-point-same-a'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 16, 'Challenge',
 'For the parabola y = 5x², find the two values of x where y = 45.', 3,
 '[{"text": "x = 3 only", "feedback": "A parabola is symmetric about its axis — if x = 3 gives y = 45, then x = -3 gives the same y-value too."}, {"text": "x = 9", "feedback": "This treats 45 ÷ 5 = 9 as the answer directly — but 9 = x², so one more step (a square root) is still needed."}, {"text": "x = 45 and x = -45", "feedback": "This treats 45 as x² directly, skipping the division by 5 first — solve 5x² = 45 for x² before taking the square root."}, {"text": "x = 3 and x = -3", "feedback": "Correct. Setting 5x² = 45 gives x² = 9, so x = 3 or x = -3."}]'::jsonb,
 'parabola-solve-for-x'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 17, 'Advanced',
 'A parabola of the form y = ax² passes through the point (4, -24). What is the value of a?', 1,
 '[{"text": "a = -6", "feedback": "This divides -24 by 4 instead of 4² = 16 — remember x is squared before being multiplied by a."}, {"text": "a = -1.5", "feedback": "Correct. Substituting (4, -24) gives -24 = a(4)² = 16a, so a = -24 ÷ 16 = -1.5."}, {"text": "a = 6", "feedback": "The sign is off — since y is negative here (-24), a must also come out negative."}, {"text": "a = -96", "feedback": "This multiplies -24 by 4 instead of dividing by 4² = 16 — isolate a by dividing both sides by 16."}]'::jsonb,
 'parabola-find-a-from-point'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 18, 'Advanced',
 'A parabola of the form y = ax² passes through the point (-4, 32). What is a, and does the parabola open up or down?', 0,
 '[{"text": "a = 2, opens upward", "feedback": "Correct. Substituting (-4, 32) gives 32 = a(-4)² = 16a, so a = 2; since a is positive, the parabola opens upward."}, {"text": "a = -2, opens downward", "feedback": "The sign is off — since y is positive here (32) while x² is always positive, a must come out positive, not negative."}, {"text": "a = 8, opens upward", "feedback": "This divides 32 by 4 instead of (-4)² = 16 — remember x is squared (and the negative sign disappears) before being multiplied by a."}, {"text": "a = 2, opens downward", "feedback": "a came out positive here, and a positive leading coefficient always means the parabola opens upward, not downward."}]'::jsonb,
 'parabola-find-a-and-direction'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 19, 'Advanced',
 'The parabola y = ax² is narrower than y = 2x² but wider than y = 6x². Which of these could be the value of a?', 2,
 '[{"text": "a = 1", "feedback": "For y = ax² to be narrower than y = 2x², |a| must be greater than 2 — a = 1 is too small."}, {"text": "a = 8", "feedback": "For y = ax² to be wider than y = 6x², |a| must be less than 6 — a = 8 is too large."}, {"text": "a = 4", "feedback": "Correct. Narrower than y = 2x² needs |a| > 2, and wider than y = 6x² needs |a| < 6, so 2 < |a| < 6 — a = 4 fits exactly between them."}, {"text": "a = 7", "feedback": "This is larger than 6, so it fails the |a| < 6 requirement — it would actually be narrower than y = 6x², not wider."}]'::jsonb,
 'parabola-width-range'),
('MPM2D', 'quadratic-relations', 'investigating-parabolas', 20, 'Advanced',
 'Which parabola is narrower: y = -8x² or y = 3x²?', 0,
 '[{"text": "y = -8x²", "feedback": "Correct. Comparing the *sizes* of the coefficients, |-8| = 8 is greater than |3| = 3, so y = -8x² is narrower, even though it opens downward."}, {"text": "y = 3x²", "feedback": "Compare the sizes of the coefficients, not their signs: |-8| = 8 is actually larger than |3| = 3, making the first parabola narrower."}, {"text": "They are the same width", "feedback": "The two coefficients have very different sizes (8 versus 3), so the two parabolas are noticeably different widths."}, {"text": "It can''t be compared since one opens downward", "feedback": "A parabola''s width depends only on the size of its coefficient, |a| — the direction it opens doesn''t affect the comparison."}]'::jsonb,
 'parabola-width-comparison-with-sign'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 5, 'Easy',
 'What is the vertex of y = (x - 3)² + 2?', 1,
 '[{"text": "(-3, 2)", "feedback": "The sign inside the bracket flips for the vertex''s x-coordinate — (x−3)² corresponds to a vertex at x = 3, not −3."}, {"text": "(3, 2)", "feedback": "Correct. In vertex form y = a(x−h)²+k, the vertex is (h, k); here h = 3 and k = 2."}, {"text": "(3, -2)", "feedback": "The constant term at the end is added directly, not subtracted — +2 means the vertex''s y-coordinate is +2."}, {"text": "(2, 3)", "feedback": "The h and k values are swapped — the number subtracted from x is the vertex''s x-coordinate, and the number added at the end is its y-coordinate."}]'::jsonb,
 'vertex-from-vertex-form'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 6, 'Easy',
 'How has y = x² been shifted to produce y = (x + 5)²?', 2,
 '[{"text": "5 units right", "feedback": "A plus sign inside the bracket shifts the graph left, not right — (x+5) moves the graph in the negative x-direction."}, {"text": "5 units up", "feedback": "There''s no constant added outside the bracket, so this transformation is purely horizontal, not vertical."}, {"text": "5 units left", "feedback": "Correct. Writing (x + 5) as (x − (−5)) shows h = −5, which shifts the graph 5 units to the left."}, {"text": "5 units down", "feedback": "There''s no constant added outside the bracket, so this transformation is purely horizontal, not vertical."}]'::jsonb,
 'horizontal-shift-identification'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 7, 'Easy',
 'How has y = x² been shifted to produce y = x² - 7?', 3,
 '[{"text": "7 units left", "feedback": "There''s no term added or subtracted inside the bracket with x, so this transformation is purely vertical, not horizontal."}, {"text": "7 units right", "feedback": "There''s no term added or subtracted inside the bracket with x, so this transformation is purely vertical, not horizontal."}, {"text": "7 units up", "feedback": "The −7 outside the squared term shifts the graph down, not up."}, {"text": "7 units down", "feedback": "Correct. Subtracting 7 outside the squared term shifts the entire graph 7 units down."}]'::jsonb,
 'vertical-shift-identification'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 8, 'Easy',
 'How has y = x² been transformed to produce y = 3x²?', 1,
 '[{"text": "Shifted 3 units up", "feedback": "There''s no constant added outside the squared term — multiplying by 3 changes the shape, not the position."}, {"text": "Vertically stretched by a factor of 3", "feedback": "Correct. Multiplying x² by 3 stretches the graph vertically, making it narrower by a factor of 3."}, {"text": "Shifted 3 units right", "feedback": "There''s no term added or subtracted inside the bracket with x — multiplying by 3 changes the shape, not the position."}, {"text": "Reflected across the x-axis", "feedback": "The coefficient 3 is positive, so the parabola still opens upward — a reflection would need a negative coefficient."}]'::jsonb,
 'vertical-stretch-identification'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 9, 'Medium',
 'What is the vertex of y = -2(x - 1)² + 4, and which way does it open?', 2,
 '[{"text": "(1, 4), opens upward", "feedback": "The leading coefficient here is −2, which is negative — that makes the parabola open downward, not upward."}, {"text": "(-1, 4), opens downward", "feedback": "The sign inside the bracket flips for the vertex''s x-coordinate — (x−1)² corresponds to a vertex at x = 1, not −1."}, {"text": "(1, 4), opens downward", "feedback": "Correct. The vertex is (h, k) = (1, 4), and since the leading coefficient −2 is negative, the parabola opens downward."}, {"text": "(1, -4), opens downward", "feedback": "The constant term at the end is added directly — +4 means the vertex''s y-coordinate is +4, not −4."}]'::jsonb,
 'vertex-and-direction-from-vertex-form'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 10, 'Medium',
 'What is the vertex of y = (x - 6)² - 3?', 0,
 '[{"text": "(6, -3)", "feedback": "Correct. In vertex form y = a(x−h)²+k, the vertex is (h, k); here h = 6 and k = −3."}, {"text": "(-6, -3)", "feedback": "The sign inside the bracket flips for the vertex''s x-coordinate — (x−6)² corresponds to a vertex at x = 6, not −6."}, {"text": "(6, 3)", "feedback": "The constant term at the end is subtracted, not added — −3 means the vertex''s y-coordinate is −3."}, {"text": "(-3, 6)", "feedback": "The h and k values are swapped — the number subtracted from x is the vertex''s x-coordinate, and the number added or subtracted at the end is its y-coordinate."}]'::jsonb,
 'vertex-from-vertex-form'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 11, 'Medium',
 'Describe how y = (x + 2)² - 5 has been transformed from y = x².', 1,
 '[{"text": "Shifted 2 right and 5 up", "feedback": "Both directions are flipped — (x+2) shifts the graph left, not right, and −5 shifts it down, not up."}, {"text": "Shifted 2 left and 5 down", "feedback": "Correct. Writing (x+2) as (x−(−2)) shows a shift of 2 units left, and the −5 outside the bracket shifts the graph 5 units down."}, {"text": "Shifted 2 left and 5 up", "feedback": "The horizontal shift (2 left) is correct, but the vertical shift is down, not up, since 5 is subtracted."}, {"text": "Shifted 2 right and 5 down", "feedback": "The vertical shift (5 down) is correct, but the horizontal shift is left, not right, since (x+2) means h = −2."}]'::jsonb,
 'combined-shift-identification'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 12, 'Medium',
 'Compared to y = x², is y = 0.5(x - 4)² narrower or wider?', 1,
 '[{"text": "Narrower", "feedback": "A coefficient smaller than 1 (like 0.5) makes a parabola grow more slowly than y = x², which makes it wider, not narrower."}, {"text": "Wider", "feedback": "Correct. Since |0.5| is smaller than 1, this parabola grows more slowly than y = x², making it wider — the horizontal shift doesn''t affect its width."}, {"text": "The same width", "feedback": "The coefficient 0.5 is different from 1, so the two parabolas actually have different widths."}, {"text": "It depends on where the vertex is", "feedback": "A parabola''s width depends only on its leading coefficient''s size — shifting the vertex doesn''t change how wide or narrow it is."}]'::jsonb,
 'vertex-form-width-comparison'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 13, 'Challenge',
 'Describe all the transformations that turn y = x² into y = -3(x + 2)² + 7.', 2,
 '[{"text": "Vertically stretched by 3, shifted 2 right and 7 up", "feedback": "The sign inside the bracket, (x+2), shifts the graph left, not right — and the negative sign in front means it''s also reflected."}, {"text": "Vertically compressed by 3, shifted 2 left and 7 up", "feedback": "A coefficient with size 3 (greater than 1) stretches the graph rather than compressing it — and the negative sign also means it''s reflected."}, {"text": "Reflected in the x-axis, stretched by 3, shifted 2 left and 7 up", "feedback": "Correct. The negative sign reflects the parabola in the x-axis, the 3 stretches it vertically, (x+2) shifts it 2 units left, and +7 shifts it 7 units up."}, {"text": "Reflected in the y-axis, stretched by 3, shifted 2 left and 7 up", "feedback": "A negative leading coefficient reflects a parabola in the x-axis (flipping it upside down), not in the y-axis."}]'::jsonb,
 'full-transformation-description'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 14, 'Challenge',
 'A parabola has vertex (-1, 4) and passes through the point (1, -4). What is its equation in vertex form?', 1,
 '[{"text": "y = 2(x + 1)² + 4", "feedback": "Substituting (1, −4) into this equation gives y = 2(2)²+4 = 12, not −4 — recheck the sign of a."}, {"text": "y = -2(x + 1)² + 4", "feedback": "Correct. Using vertex form y = a(x+1)²+4 and substituting (1, -4): -4 = a(1+1)²+4, so -4 = 4a+4, giving a = -2."}, {"text": "y = -2(x - 1)² + 4", "feedback": "The sign inside the bracket should match the vertex''s x-coordinate directly: a vertex at x = −1 means (x+1), not (x−1)."}, {"text": "y = 2(x + 1)² - 4", "feedback": "The constant term should be the vertex''s y-coordinate, which is +4, not −4 — that number belongs to the given point, not the vertex."}]'::jsonb,
 'vertex-form-from-point'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 15, 'Challenge',
 'For the parabola y = 2(x - 3)² - 5, what is its y-intercept (the value of y when x = 0)?', 3,
 '[{"text": "-5", "feedback": "This is just the vertex''s y-coordinate, k — substitute x = 0 into the full equation instead."}, {"text": "18", "feedback": "Recheck the sign: 2(0-3)² is 2(9) = 18, but the -5 still needs to be subtracted afterward."}, {"text": "-23", "feedback": "Recheck the calculation: 2(0-3)² = 2(9) = 18, not a value that leads to -23 once -5 is subtracted."}, {"text": "13", "feedback": "Correct. Substituting x = 0 gives y = 2(0-3)² - 5 = 2(9) - 5 = 18 - 5 = 13."}]'::jsonb,
 'vertex-form-find-y-intercept'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 16, 'Challenge',
 'Which parabola is narrower: y = 4(x - 1)² + 2 or y = -0.5(x + 3)² - 1?', 0,
 '[{"text": "y = 4(x - 1)² + 2", "feedback": "Correct. Comparing the sizes of the coefficients, |4| is much greater than |-0.5|, so this parabola is narrower — the shifts don''t affect width."}, {"text": "y = -0.5(x + 3)² - 1", "feedback": "Compare the sizes of the coefficients, not the shifts: |4| is much larger than |-0.5|, making the first parabola narrower."}, {"text": "They are the same width", "feedback": "The coefficients here, 4 and -0.5, have very different sizes, so the two parabolas are noticeably different widths."}, {"text": "It can''t be compared since they open in different directions", "feedback": "A parabola''s width depends only on the size of its leading coefficient — the direction it opens doesn''t affect the comparison."}]'::jsonb,
 'vertex-form-width-comparison-two-parabolas'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 17, 'Advanced',
 'A parabola has vertex (h, 3) and passes through both (2, 11) and (6, 11). What is its equation in vertex form?', 1,
 '[{"text": "y = (x - 2)² + 3", "feedback": "This uses one of the given points directly as the vertex''s x-coordinate — but the vertex''s x-coordinate should be found using the symmetry between the two equal-height points first."}, {"text": "y = 2(x - 4)² + 3", "feedback": "Correct. Since (2, 11) and (6, 11) share the same y-value, the axis of symmetry lies exactly halfway between them, at x = 4; substituting (2, 11) into y = a(x-4)²+3 gives 11 = a(4)+3, so a = 2."}, {"text": "y = 4(x - 4)² + 3", "feedback": "The axis of symmetry (x = 4, halfway between 2 and 6) is right, but recheck solving 11 = a(2-4)²+3 for a — it isn''t 4."}, {"text": "y = 2(x - 4)² - 3", "feedback": "The constant term should be the vertex''s given y-coordinate, +3, not −3."}]'::jsonb,
 'vertex-form-from-symmetric-points'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 18, 'Advanced',
 'Expand y = -(x - 5)² + 8 into standard form.', 2,
 '[{"text": "y = -x² + 5x - 17", "feedback": "The middle term''s coefficient is off — expanding -(x-5)² gives -x²+10x-25, not -x²+5x."}, {"text": "y = -x² - 10x + 33", "feedback": "The sign of the middle term is flipped — expanding -(x-5)² gives +10x, since squaring removes the negative sign on 5 before the outer negative is applied."}, {"text": "y = -x² + 10x - 17", "feedback": "Correct. (x-5)² = x²-10x+25, so -(x-5)²+8 = -x²+10x-25+8 = -x²+10x-17."}, {"text": "y = x² + 10x - 17", "feedback": "The leading term''s sign is off — the negative sign in front of the bracket applies to the whole expansion, including the x² term."}]'::jsonb,
 'vertex-form-to-standard-form'),
('MPM2D', 'quadratic-relations', 'transformations-vertex-form', 19, 'Advanced',
 'A parabola has vertex (3, -2) and a y-intercept of -11. What is its equation in vertex form?', 2,
 '[{"text": "y = (x - 3)² - 2", "feedback": "Substituting x = 0 into this equation gives y = 9-2 = 7, not -11 — solve -11 = a(0-3)²-2 for a instead of assuming a = 1."}, {"text": "y = -2(x - 3)² - 2", "feedback": "Substituting x = 0 into this equation gives y = -18-2 = -20, not -11 — recheck solving -11 = a(0-3)²-2 = 9a-2 for a."}, {"text": "y = -(x - 3)² - 2", "feedback": "Correct. Using y = a(x-3)²-2 and substituting the y-intercept (0, -11): -11 = a(0-3)²-2, so -11 = 9a-2, giving a = -1, and y = -(x-3)²-2."}, {"text": "y = 9(x - 3)² - 2", "feedback": "This uses 9 (the value of (0-3)²) directly as a instead of solving 9a-2=-11 for a."}]'::jsonb,
 'vertex-form-from-vertex-and-y-intercept'),
