 'binomial-expansion-basic'),
('MPM2D', 'quadratic-relations', 'expanding-and-simplifying', 9, 'Medium',
 'Expand and simplify: (3x + 1)(2x - 4).', 1,
 '[{"text": "6x² - 4", "feedback": "This multiplies only the first and last terms and skips the two cross terms entirely."}, {"text": "6x² - 10x - 4", "feedback": "Correct. (3x)(2x)+(3x)(-4)+(1)(2x)+(1)(-4) = 6x²-12x+2x-4 = 6x²-10x-4."}, {"text": "6x² + 10x - 4", "feedback": "The sign on the middle term is flipped — recompute -12x + 2x, which is negative."}, {"text": "6x² - 10x + 4", "feedback": "The sign on the constant term is off — recheck (1)(-4)."}]'::jsonb,
 'binomial-expansion-leading-coefficient'),
('MPM2D', 'quadratic-relations', 'expanding-and-simplifying', 10, 'Medium',
 'Expand and simplify: (4x - 2)(x + 3).', 1,
