('MPM2D', 'quadratic-relations', 'completing-the-square', 19, 'Advanced',
 'Find the minimum value of y = x² - 14x + 53 by completing the square.', 1,
 '[{"text": "The minimum value is 49, at x = 7", "feedback": "49 is (14÷2)², the number used partway through completing the square — one more step (combining it with 53) is still needed."}, {"text": "The minimum value is 4, at x = 7", "feedback": "Correct. Completing the square gives y = (x-7)² + (53-49) = (x-7)² + 4; since (x-7)² can never be negative, the smallest y can be is 4, occurring at x = 7."}, {"text": "The minimum value is 53, at x = 0", "feedback": "53 is only the y-intercept (the value when x = 0) — the actual minimum occurs at the vertex, found by completing the square."}, {"text": "The minimum value is 4, at x = -7", "feedback": "The x-coordinate of the vertex has the wrong sign — completing the square gives (x-7)², placing the vertex at x = 7, not x = -7."}]'::jsonb,
 'completing-square-find-minimum'),
('MPM2D', 'quadratic-relations', 'completing-the-square', 20, 'Advanced',
 'Find the maximum value of y = -3x² + 18x - 20 by completing the square.', 0,
 '[{"text": "The maximum value is 7, at x = 3", "feedback": "Correct. Factoring and completing the square gives y = -3(x-3)² + 7; since -3(x-3)² can never be positive, the largest y can be is 7, occurring at x = 3."}, {"text": "The maximum value is -20, at x = 0", "feedback": "-20 is only the y-intercept (the value when x = 0) — the actual maximum occurs at the vertex, found by completing the square."}, {"text": "The maximum value is 7, at x = -3", "feedback": "The x-coordinate of the vertex has the wrong sign — completing the square gives (x-3)², placing the vertex at x = 3, not x = -3."}, {"text": "The maximum value is 27, at x = 3", "feedback": "27 is the value of -3×9 partway through the calculation — one more step (adding the remaining -20+27) is still needed."}]'::jsonb,
 'completing-square-find-maximum'),
('MPM2D', 'quadratic-relations', 'quadratic-formula', 5, 'Easy',
 'In the quadratic formula x = (-b ± √(b²-4ac)) ÷ 2a, what does the ''2a'' represent?', 1,
 '[{"text": "Part of the discriminant", "feedback": "The discriminant is the expression b²-4ac, under the square root — 2a is a separate part of the formula, outside the root."}, {"text": "The denominator of the whole expression", "feedback": "Correct. Everything above the fraction bar, -b ± √(b²-4ac), is divided by 2a — twice the leading coefficient."}, {"text": "The coefficient of x²", "feedback": "The coefficient of x² is just a on its own — 2a is that value doubled, used as the formula''s denominator."}, {"text": "The y-intercept", "feedback": "The y-intercept of a quadratic is c, found by substituting x = 0 — unrelated to the 2a in this formula."}]'::jsonb,
 'quadratic-formula-parts'),
('MPM2D', 'quadratic-relations', 'quadratic-formula', 6, 'Easy',
 'For the equation x² - 5x + 6 = 0, what are the values of a, b, and c?', 0,
 '[{"text": "a = 1, b = -5, c = 6", "feedback": "Correct. Matching x²-5x+6=0 to ax²+bx+c=0 gives a=1 (the coefficient of x²), b=-5 (the coefficient of x), and c=6 (the constant term)."}, {"text": "a = 1, b = 5, c = 6", "feedback": "The sign of b is off — the coefficient of x here is -5, not 5."}, {"text": "a = -5, b = 1, c = 6", "feedback": "The values of a and b are swapped — a is the coefficient of x², and b is the coefficient of x."}, {"text": "a = 1, b = -5, c = -6", "feedback": "The sign of c is off — the constant term here is +6, not -6."}]'::jsonb,
 'identify-a-b-c'),
('MPM2D', 'quadratic-relations', 'quadratic-formula', 7, 'Easy',
 'Use the quadratic formula to solve x² - 5x + 6 = 0.', 2,
 '[{"text": "x = 5 and x = 6", "feedback": "These reuse the equation''s own coefficients directly instead of applying the quadratic formula."}, {"text": "x = -2 and x = -3", "feedback": "The signs are flipped — recheck (-b ± √(b²-4ac)) ÷ 2a with b = -5, which makes -b positive."}, {"text": "x = 2 and x = 3", "feedback": "Correct. With a=1, b=-5, c=6: the discriminant is 25-24=1, so x = (5 ± 1) ÷ 2, giving x = 3 or x = 2."}, {"text": "x = 1 and x = 6", "feedback": "These don''t satisfy the original equation — recompute using a=1, b=-5, c=6 in the quadratic formula."}]'::jsonb,
 'quadratic-formula-basic-solve'),
('MPM2D', 'quadratic-relations', 'quadratic-formula', 8, 'Easy',
 'For the equation 2x² + 3x - 2 = 0, what are the values of a, b, and c?', 1,
 '[{"text": "a = 2, b = 3, c = 2", "feedback": "The sign of c is off — the constant term here is -2, not 2."}, {"text": "a = 2, b = 3, c = -2", "feedback": "Correct. Matching 2x²+3x-2=0 to ax²+bx+c=0 gives a=2, b=3, and c=-2."}, {"text": "a = 3, b = 2, c = -2", "feedback": "The values of a and b are swapped — a is the coefficient of x², and b is the coefficient of x."}, {"text": "a = 2, b = -3, c = -2", "feedback": "The sign of b is off — the coefficient of x here is +3, not -3."}]'::jsonb,
 'identify-a-b-c'),
