('MPM2D', 'trigonometry', 'solving-right-triangles', 7, 'Easy',
 'A right triangle has a hypotenuse of 10 and an angle of 30°. What is the length of the side opposite the 30° angle?', 2,
 '[{"text": "8.7", "feedback": "This looks like it used cosine instead of sine — the opposite side needs sin(30°), not cos(30°)."}, {"text": "10", "feedback": "This just reuses the hypotenuse — the opposite side is shorter than the hypotenuse in a right triangle."}, {"text": "5", "feedback": "Correct. opposite = hypotenuse × sin(30°) = 10 × 0.5 = 5."}, {"text": "17.3", "feedback": "This looks like it divided by sin(30°) instead of multiplying — opposite = hypotenuse × sin(angle)."}]'::jsonb,
 'solving-right-triangle-side'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 8, 'Easy',
 'A right triangle has an adjacent side of 8 and an angle of 60°. What is the length of the hypotenuse?', 1,
 '[{"text": "4", "feedback": "This multiplies 8 by cos(60°) instead of dividing — the hypotenuse should be larger than the adjacent side, not smaller."}, {"text": "16", "feedback": "Correct. hypotenuse = adjacent ÷ cos(60°) = 8 ÷ 0.5 = 16."}, {"text": "13.9", "feedback": "This looks like it used sine instead of cosine — the adjacent side relates to the hypotenuse through cosine."}, {"text": "8", "feedback": "This just reuses the adjacent side — the hypotenuse must be longer than either leg in a right triangle."}]'::jsonb,
 'solving-right-triangle-side'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 9, 'Easy',
 'A right triangle has an opposite side of 6 and an angle of 45°. What is the length of the adjacent side?', 3,
 '[{"text": "8.5", "feedback": "This looks like it multiplied by √2 instead of dividing by tan(45°) — recompute 6 ÷ tan(45°)."}, {"text": "4.2", "feedback": "This looks like it used sine or cosine instead of tangent — the relationship between opposite and adjacent uses tangent."}, {"text": "12", "feedback": "This doubles the opposite side rather than dividing by tan(45°), which equals 1."}, {"text": "6", "feedback": "Correct. adjacent = opposite ÷ tan(45°) = 6 ÷ 1 = 6, since tan(45°) = 1."}]'::jsonb,
 'solving-right-triangle-side'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 10, 'Easy',
 'In a right triangle, the two acute angles add to 90°. If one of them is 35°, what is the other?', 1,
 '[{"text": "35°", "feedback": "Both acute angles being equal would only work if the given angle were exactly 45° — here it''s 35°."}, {"text": "55°", "feedback": "Correct. The two acute angles in a right triangle are complementary, adding to 90°: 90° − 35° = 55°."}, {"text": "65°", "feedback": "This subtracts 35° from 100° instead of 90° — remember the two acute angles of a right triangle add to exactly 90°."}, {"text": "125°", "feedback": "This adds 35° to 90° instead of subtracting — the two acute angles together must total 90°, not exceed it."}]'::jsonb,
 'complementary-acute-angles'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 11, 'Medium',
 'A right triangle has a hypotenuse of 15 and an angle of 40°. What is the length of the side adjacent to that angle, to one decimal place?', 1,
 '[{"text": "9.6", "feedback": "This looks like it used sine instead of cosine — the adjacent side relates to the hypotenuse through cosine."}, {"text": "11.5", "feedback": "Correct. adjacent = hypotenuse × cos(40°) = 15 × cos(40°) ≈ 11.5."}, {"text": "17.8", "feedback": "This looks like it divided by cos(40°) instead of multiplying — adjacent = hypotenuse × cos(angle)."}, {"text": "15.0", "feedback": "This just reuses the hypotenuse — the adjacent side must be shorter than the hypotenuse."}]'::jsonb,
 'solving-right-triangle-side'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 12, 'Medium',
 'A right triangle has an opposite side of 9 and an adjacent side of 12. What is the angle θ opposite the 9 side, to the nearest degree?', 2,
 '[{"text": "θ ≈ 53°", "feedback": "This looks like the complementary angle was found instead — apply tan⁻¹(9÷12) directly for θ."}, {"text": "θ ≈ 48°", "feedback": "Recheck the ratio used — θ = tan⁻¹(opposite ÷ adjacent) = tan⁻¹(9÷12), which doesn''t give this value."}, {"text": "θ ≈ 37°", "feedback": "Correct. θ = tan⁻¹(9 ÷ 12) = tan⁻¹(0.75) ≈ 36.9°, which rounds to 37°."}, {"text": "θ ≈ 75°", "feedback": "This looks like tan⁻¹ was applied to 12÷9 instead of 9÷12 — recheck which side is opposite θ."}]'::jsonb,
 'solving-right-triangle-angle'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 13, 'Challenge',
 'A right triangle has an opposite side of 14 and an angle of 50°. Find the hypotenuse, then use it to find the adjacent side (both to one decimal place).', 1,
 '[{"text": "Hypotenuse ≈ 21.8, adjacent ≈ 14.0", "feedback": "The hypotenuse doesn''t match 14÷sin(50°) — recompute that first step before finding the adjacent side."}, {"text": "Hypotenuse ≈ 18.3, adjacent ≈ 11.7", "feedback": "Correct. hypotenuse = 14 ÷ sin(50°) ≈ 18.3, and adjacent = 14 ÷ tan(50°) ≈ 11.7 (or equivalently, hypotenuse × cos(50°))."}, {"text": "Hypotenuse ≈ 18.3, adjacent ≈ 16.7", "feedback": "The hypotenuse is right, but recompute the adjacent side using adjacent = hypotenuse × cos(50°) or 14 ÷ tan(50°)."}, {"text": "Hypotenuse ≈ 10.7, adjacent ≈ 9.0", "feedback": "This looks like cosine was used instead of sine for the hypotenuse — opposite relates to the hypotenuse through sine."}]'::jsonb,
 'solving-right-triangle-two-step'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 14, 'Challenge',
 'A right triangle has a hypotenuse of 25 and an adjacent side of 7. Find both acute angles, to the nearest degree.', 0,
 '[{"text": "74° and 16°", "feedback": "Correct. cos⁻¹(7÷25) ≈ 74°, and since the two acute angles are complementary, the other is 90°−74° = 16°."}, {"text": "16° and 74°, but using sin⁻¹(7÷25) for the first", "feedback": "sin⁻¹(7÷25) doesn''t give 16° — the side 7 is adjacent to the angle being found, so cosine (not sine) is the correct ratio to start with."}, {"text": "54° and 36°", "feedback": "Recheck cos⁻¹(7÷25) directly — these values don''t match that calculation."}, {"text": "73° and 17°", "feedback": "Close, but recompute cos⁻¹(7÷25) more precisely, then subtract from 90° for the second angle."}]'::jsonb,
 'solving-right-triangle-both-angles'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 15, 'Challenge',
 'A right triangle''s legs are in the ratio 3:4, and its hypotenuse is 15. Find both legs.', 2,
 '[{"text": "6 and 8", "feedback": "Check: 6²+8² = 100, not 15² = 225 — these legs don''t actually produce a hypotenuse of 15."}, {"text": "6.4 and 8.6", "feedback": "These don''t maintain the exact 3:4 ratio — set up legs as 3k and 4k, then solve using the Pythagorean theorem."}, {"text": "9 and 12", "feedback": "Correct. Let the legs be 3k and 4k; then (3k)²+(4k)² = 15² gives 25k² = 225, so k = 3, and the legs are 3(3)=9 and 4(3)=12."}, {"text": "7.5 and 7.5", "feedback": "Equal legs would mean a 1:1 ratio, not 3:4 — set up legs as 3k and 4k and solve for k instead."}]'::jsonb,
 'solving-right-triangle-ratio-legs'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 16, 'Challenge',
 'A right triangle has an area of 24 and one leg of 6. Find the other leg and the hypotenuse.', 3,
 '[{"text": "Other leg = 4, hypotenuse = 7.2", "feedback": "Recheck the area formula: ½ × 6 × (other leg) = 24 — this other leg value doesn''t satisfy that equation."}, {"text": "Other leg = 12, hypotenuse = 13.4", "feedback": "Recheck the area formula: ½ × 6 × (other leg) = 24 gives a different value for the other leg than 12."}, {"text": "Other leg = 8, hypotenuse = 12", "feedback": "The other leg (8) is correct, but recompute the hypotenuse using the Pythagorean theorem: √(6²+8²)."}, {"text": "Other leg = 8, hypotenuse = 10", "feedback": "Correct. Since area = ½(6)(other leg) = 24, the other leg = 8; then the hypotenuse is √(6²+8²) = √100 = 10."}]'::jsonb,
 'solving-right-triangle-from-area'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 17, 'Advanced',
 'A 13 m ladder leans against a wall, reaching 12 m up. Find the angle between the ladder and the ground, and the distance from the wall''s base to the foot of the ladder.', 1,
 '[{"text": "Angle ≈ 23°, distance = 5 m", "feedback": "The distance (5 m) is correct, but recompute the angle using sin⁻¹(12÷13), not this value."}, {"text": "Angle ≈ 67°, distance = 5 m", "feedback": "Correct. The angle is sin⁻¹(12÷13) ≈ 67°, and the distance from the wall is √(13²−12²) = √25 = 5 m."}, {"text": "Angle ≈ 67°, distance = 1 m", "feedback": "The angle is correct, but recompute the distance using the Pythagorean theorem: √(13²−12²)."}, {"text": "Angle ≈ 43°, distance = 5 m", "feedback": "Recompute the angle using sin⁻¹(12÷13) directly — this value doesn''t match that calculation."}]'::jsonb,
 'solving-right-triangle-ladder-application'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 18, 'Advanced',
 'A right triangle''s two legs differ by 7, and its hypotenuse is 13. Find both legs.', 2,
 '[{"text": "6 and 13", "feedback": "Check: 6²+13² = 205, not 13² = 169 — 13 can''t be used as both the hypotenuse and a leg."}, {"text": "6 and -1", "feedback": "A negative leg length doesn''t make physical sense — reject that solution and use the positive one from the quadratic."}, {"text": "5 and 12", "feedback": "Correct. Let the legs be a and a+7: a²+(a+7)²=169 expands to 2a²+14a-120=0, or a²+7a-60=0, which factors as (a+12)(a-5)=0; rejecting the negative solution leaves a=5, so the legs are 5 and 12."}, {"text": "4 and 11", "feedback": "Check: 4²+11² = 137, not 13² = 169 — these legs don''t produce the given hypotenuse."}]'::jsonb,
 'solving-right-triangle-legs-differ'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 19, 'Advanced',
 'A right triangle has a hypotenuse of 20 and an area of 96. Find the two legs.', 0,
 '[{"text": "16 and 12", "feedback": "Correct. With legs p and q: p²+q²=400 and pq=192 (from area = pq÷2 = 96); solving gives (p+q)²=784 and (p-q)²=16, so p+q=28 and p-q=4, giving p=16 and q=12."}, {"text": "18 and 10", "feedback": "Check: 18²+10² = 424, not 400 — these legs don''t satisfy the Pythagorean relationship for a hypotenuse of 20."}, {"text": "15 and 13", "feedback": "Check the area: 15×13÷2 = 97.5, not 96 — these legs don''t produce the given area."}, {"text": "14 and 14", "feedback": "Equal legs would need a different relationship between the hypotenuse and area — check both 14²+14²=400 and 14×14÷2=96 to see this doesn''t hold."}]'::jsonb,
 'solving-right-triangle-from-hyp-and-area'),
('MPM2D', 'trigonometry', 'solving-right-triangles', 20, 'Advanced',
 'A right triangle''s two acute angles are in the ratio 1:2. Find both acute angles.', 3,
 '[{"text": "45° and 45°", "feedback": "A 1:1 ratio would give two equal angles — but the ratio given here is 1:2, not 1:1."}, {"text": "20° and 70°", "feedback": "Check this ratio: 20:70 simplifies to 2:7, not 1:2 — set up x and 2x, then solve x+2x=90."}, {"text": "40° and 50°", "feedback": "Check this ratio: 40:50 simplifies to 4:5, not 1:2 — set up x and 2x, then solve x+2x=90."}, {"text": "30° and 60°", "feedback": "Correct. Let the angles be x and 2x; since they''re complementary, x+2x=90 gives 3x=90, so x=30, and the angles are 30° and 60°."}]'::jsonb,
 'solving-right-triangle-angle-ratio'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 5, 'Easy',
 'A person on top of a cliff looks down at a boat. The angle between their horizontal line of sight and their line of sight to the boat is called the angle of ___.', 1,
 '[{"text": "Elevation", "feedback": "Elevation is measured looking upward from horizontal, such as from the boat looking up at the person — here the person is looking down."}, {"text": "Depression", "feedback": "Correct. Looking downward from horizontal to a lower point is the angle of depression."}, {"text": "Reflection", "feedback": "\"Angle of reflection\" is a physics term used for light or waves bouncing off a surface, not for a line of sight to an object."}, {"text": "Inclination", "feedback": "\"Angle of inclination\" isn''t the standard term used in this situation — it''s called the angle of depression."}]'::jsonb,
 'elevation-vs-depression-terminology'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 6, 'Easy',
 'The angle of elevation from point A to point B, and the angle of depression from point B to point A, are always related how?', 0,
 '[{"text": "They are equal", "feedback": "Correct. These two angles are alternate angles formed by a transversal (the line of sight) between two parallel horizontal lines, so they''re always equal."}, {"text": "They add to 90°", "feedback": "90° would make them complementary, but that''s not the relationship here — they''re actually equal to each other."}, {"text": "They add to 180°", "feedback": "180° would make them supplementary, but that''s not the relationship here — they''re actually equal to each other."}, {"text": "There''s no fixed relationship between them", "feedback": "These two angles are alternate angles formed between parallel horizontal lines, which are always exactly equal."}]'::jsonb,
 'elevation-depression-alternate-angles-relationship'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 7, 'Easy',
 'As you walk closer to the base of a tall building (staying the same height), does the angle of elevation to its top increase or decrease?', 0,
 '[{"text": "It increases", "feedback": "Correct. As the horizontal distance shrinks while the building''s height stays the same, the line of sight gets steeper, increasing the angle of elevation."}, {"text": "It decreases", "feedback": "Getting closer to a tall object makes you tilt your head back further to see the top, which means the angle gets larger, not smaller."}, {"text": "It stays the same", "feedback": "The angle of elevation depends on the ratio of height to horizontal distance — since the distance is changing, the angle changes too."}, {"text": "It becomes an angle of depression instead", "feedback": "Depression only applies when looking downward from a higher point — here, the observer stays at ground level."}]'::jsonb,
 'elevation-angle-distance-relationship'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 8, 'Easy',
 'You stand on the ground and look up at a kite in the sky. From what reference line is this angle measured?', 2,
 '[{"text": "The vertical line straight up", "feedback": "The angle is measured from the horizontal, not from a vertical reference line."}, {"text": "The line to the kite''s shadow", "feedback": "The kite''s shadow isn''t part of how the angle of elevation is defined — it''s measured from a horizontal line of sight."}, {"text": "The horizontal", "feedback": "Correct. The angle of elevation is always measured from a horizontal line of sight upward to the object."}, {"text": "The ground directly below the kite", "feedback": "The reference line for an angle of elevation is horizontal, in the direction the observer is facing — not a vertical line to a point on the ground."}]'::jsonb,
 'elevation-depression-terminology'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 9, 'Medium',
 'From a point 40 m from the base of a tower, the angle of elevation to the top is 35°. How tall is the tower, to the nearest metre?', 2,
 '[{"text": "33 m", "feedback": "This looks like it used cos(35°) instead of tan(35°) — with the horizontal distance known and the height unknown, tangent is the ratio to use."}, {"text": "23 m", "feedback": "This is a bit low — recompute 40 × tan(35°) carefully."}, {"text": "28 m", "feedback": "Correct. tan(35°) = height ÷ 40, so height = 40 × tan(35°) ≈ 28 m."}, {"text": "70 m", "feedback": "This looks like it used sin(35°) with 40 m treated as the hypotenuse — but 40 m is the adjacent (horizontal) side here, not the hypotenuse."}]'::jsonb,
 'elevation-depression-tangent-setup'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 10, 'Medium',
 'From the top of a 25 m building, the angle of depression to a car is 20°. How far is the car from the base of the building, to the nearest metre?', 1,
 '[{"text": "9 m", "feedback": "This looks like it used tan(20°) × 25 instead of dividing — since 25 m is the opposite side and the distance is adjacent, divide by tan(20°) instead."}, {"text": "69 m", "feedback": "Correct. The angle of depression equals the angle of elevation from the car (alternate angles), so tan(20°) = 25 ÷ d, giving d = 25 ÷ tan(20°) ≈ 69 m."}, {"text": "27 m", "feedback": "This looks like it used cos(20°) — with the building''s height as the opposite side and the distance as adjacent, tangent is the correct ratio."}, {"text": "59 m", "feedback": "This looks like a different ratio was used — recompute 25 ÷ tan(20°) carefully."}]'::jsonb,
 'angle-of-depression-alternate-angles'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 11, 'Medium',
 'A person stands 60 m from a tree and measures the angle of elevation to its top as 28°. How tall is the tree, to one decimal place?', 3,
 '[{"text": "53.0 m", "feedback": "This looks like it used cos(28°) instead of tan(28°) — with the horizontal distance known and the height unknown, tangent is the ratio to use."}, {"text": "66.0 m", "feedback": "This looks like it divided 60 by tan(28°) instead of multiplying — height = distance × tan(angle)."}, {"text": "28.2 m", "feedback": "This looks like it used sin(28°) with 60 m treated as the hypotenuse — but 60 m is the adjacent (horizontal) side here."}, {"text": "31.9 m", "feedback": "Correct. tan(28°) = height ÷ 60, so height = 60 × tan(28°) ≈ 31.9 m."}]'::jsonb,
 'elevation-depression-tangent-setup'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 12, 'Medium',
 'From the top of a 45 m cliff, the angle of depression to a boat is 15°. How far is the boat from the base of the cliff, to the nearest metre?', 0,
 '[{"text": "168 m", "feedback": "Correct. The angle of depression equals the angle of elevation from the boat, so tan(15°) = 45 ÷ d, giving d = 45 ÷ tan(15°) ≈ 168 m."}, {"text": "12 m", "feedback": "This looks like it used tan(15°) × 45 instead of dividing — since 45 m is the opposite side and the distance is adjacent, divide by tan(15°) instead."}, {"text": "46 m", "feedback": "This looks like it used sin(15°) or cos(15°) — with the cliff''s height as the opposite side and the distance as adjacent, tangent is the correct ratio."}, {"text": "174 m", "feedback": "Recompute 45 ÷ tan(15°) more precisely — this doesn''t quite match that calculation."}]'::jsonb,
 'angle-of-depression-alternate-angles'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 13, 'Challenge',
 'A person 1.7 m tall stands 30 m from a tower and measures the angle of elevation to its top as 42°. Find the tower''s height, to one decimal place.', 2,
 '[{"text": "27.0 m", "feedback": "This is 30 × tan(42°) alone — remember to add the observer''s own eye height, since the angle is measured from their eyes, not the ground."}, {"text": "30.4 m", "feedback": "Recompute 30 × tan(42°) more precisely, then add the observer''s height of 1.7 m."}, {"text": "28.7 m", "feedback": "Correct. The height above eye level is 30 × tan(42°) ≈ 27.0 m; adding the observer''s own height of 1.7 m gives a total tower height of about 28.7 m."}, {"text": "31.7 m", "feedback": "This adds 1.7 to a slightly incorrect value of 30 × tan(42°) — recompute that product first."}]'::jsonb,
 'elevation-with-observer-height'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 14, 'Challenge',
 'From a lighthouse 55 m tall, the angle of depression to a ship is 8°. Find the distance to the ship, to the nearest metre.', 1,
 '[{"text": "8 m", "feedback": "This reuses the angle itself as if it were a distance — apply tan(8°) = 55 ÷ d and solve for d instead."}, {"text": "391 m", "feedback": "Correct. tan(8°) = 55 ÷ d, so d = 55 ÷ tan(8°) ≈ 391 m."}, {"text": "55 m", "feedback": "This just reuses the lighthouse''s height — the distance to the ship is a separate value, found using the tangent ratio."}, {"text": "7736 m", "feedback": "This looks like it divided by tan(8°) twice, or made another arithmetic slip — recompute 55 ÷ tan(8°) carefully."}]'::jsonb,
 'angle-of-depression-large-distance'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 15, 'Challenge',
 'Two points on the ground are 50 m apart and in line with the base of a tower. The angles of elevation to the top of the tower from these points are 30° (farther point) and 50° (closer point). Find the tower''s height, to one decimal place.', 3,
 '[{"text": "25.0 m", "feedback": "This doesn''t come from setting up both tangent ratios and solving simultaneously — set h ÷ tan(30°) and h ÷ tan(50°) as the two distances, which differ by 50 m."}, {"text": "59.6 m", "feedback": "Recheck the setup: the difference between the two horizontal distances (h÷tan(30°) and h÷tan(50°)) should equal 50, not their sum."}, {"text": "64.3 m", "feedback": "This doesn''t satisfy the equation h(1/tan(30°) − 1/tan(50°)) = 50 — recompute using both angles together."}, {"text": "56.0 m", "feedback": "Correct. Let h be the height; the two horizontal distances are h/tan(30°) and h/tan(50°), differing by 50 m: h(1/tan(30°) − 1/tan(50°)) = 50, giving h ≈ 56.0 m."}]'::jsonb,
 'elevation-two-point-problem'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 16, 'Challenge',
 'From the top of a 40 m tower, the angles of depression to two cars on the same side are 25° and 40°. Find the distance between the cars, to one decimal place.', 0,
 '[{"text": "38.1 m", "feedback": "Correct. The two cars'' distances from the tower''s base are 40÷tan(25°) ≈ 85.8 m and 40÷tan(40°) ≈ 47.7 m; the distance between them is the difference, about 38.1 m."}, {"text": "133.5 m", "feedback": "This adds the two individual distances instead of subtracting them — the two cars are on the *same* side, so the gap between them is a difference, not a sum."}, {"text": "85.8 m", "feedback": "This is only the farther car''s distance from the tower''s base — the closer car''s distance still needs to be subtracted."}, {"text": "47.7 m", "feedback": "This is only the closer car''s distance from the tower''s base — the farther car''s distance still needs to be subtracted from it."}]'::jsonb,
 'elevation-two-angle-distance-between'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 17, 'Advanced',
 'Two people stand on opposite sides of a tower, 100 m apart in total. Their angles of elevation to the top are 35° and 50°. Find the tower''s height, to one decimal place.', 1,
 '[{"text": "35.7 m", "feedback": "This doesn''t satisfy h/tan(35°) + h/tan(50°) = 100 — recompute using both angles together, since the two people are on opposite sides."}, {"text": "44.1 m", "feedback": "Correct. Since the two people are on opposite sides, their distances from the tower (h/tan(35°) and h/tan(50°)) add up to 100 m: h(1/tan(35°) + 1/tan(50°)) = 100, giving h ≈ 44.1 m."}, {"text": "50.0 m", "feedback": "This doesn''t come from solving the combined equation — set up h/tan(35°) + h/tan(50°) = 100 and solve for h."}, {"text": "83.9 m", "feedback": "This is too large — recheck the equation h(1/tan(35°) + 1/tan(50°)) = 100 for h."}]'::jsonb,
 'elevation-opposite-sides-problem'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 18, 'Advanced',
 'A plane flying at an altitude of 3000 m has an angle of depression of 12° to an airport. How far (along the ground) is the plane from the airport, to the nearest metre?', 2,
 '[{"text": "637 m", "feedback": "This looks like it used tan(12°) × 3000 instead of dividing — since 3000 m is the opposite side and the ground distance is adjacent, divide by tan(12°) instead."}, {"text": "3000 m", "feedback": "This just reuses the altitude — the ground distance is a separate value, found using the tangent ratio."}, {"text": "14 114 m", "feedback": "Correct. tan(12°) = 3000 ÷ d, so d = 3000 ÷ tan(12°) ≈ 14 114 m."}, {"text": "3068 m", "feedback": "This looks like it used cosine instead of tangent — with the altitude as the opposite side and the ground distance as adjacent, tangent is the correct ratio."}]'::jsonb,
 'elevation-depression-large-scale'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 19, 'Advanced',
 'A surveyor on top of an 80 m hill sees two objects in the same direction, at angles of depression 10° and 35°. Find the distance between the two objects, to one decimal place.', 3,
 '[{"text": "453.7 m", "feedback": "This adds the two individual distances instead of subtracting them — since both objects are in the same direction, the gap between them is a difference, not a sum."}, {"text": "113.9 m", "feedback": "This is only the closer object''s distance from the hill''s base — the farther object''s distance still needs to be subtracted from it."}, {"text": "341.1 m", "feedback": "Recompute both distances (80÷tan(10°) and 80÷tan(35°)) individually before finding their difference."}, {"text": "339.5 m", "feedback": "Correct. The two objects'' distances from the hill''s base are 80÷tan(10°) ≈ 453.7 m and 80÷tan(35°) ≈ 114.2 m; the distance between them is the difference, about 339.5 m."}]'::jsonb,
 'elevation-two-angle-distance-between'),
('MPM2D', 'trigonometry', 'elevation-and-depression', 20, 'Advanced',
 'A 1.8 m tall observer stands 40 m from a tower and measures the angle of elevation to its top as 22°. Find the height of the tower, to one decimal place.', 0,
 '[{"text": "18.0 m", "feedback": "Correct. The height above eye level is 40 × tan(22°) ≈ 16.2 m; adding the observer''s own height of 1.8 m gives a total tower height of about 18.0 m."}, {"text": "16.2 m", "feedback": "This is 40 × tan(22°) alone — remember to add the observer''s own eye height, since the angle is measured from their eyes, not the ground."}, {"text": "21.8 m", "feedback": "This adds 1.8 to a slightly incorrect value — recompute 40 × tan(22°) more precisely first."}, {"text": "41.8 m", "feedback": "This just adds the observer''s height to the horizontal distance — the vertical rise above eye level (40×tan(22°)) is what needs to be added instead."}]'::jsonb,
 'elevation-with-observer-height'),
('MPM2D', 'trigonometry', 'sine-law', 5, 'Easy',
 'In the sine law, a/sin A = b/sin B = c/sin C, what must a side and the angle paired with it in the same fraction have in common?', 1,
 '[{"text": "They must both be the largest in the triangle", "feedback": "The sine law pairs a side with an angle regardless of size — the key requirement is about their position in the triangle, not which is largest."}, {"text": "The angle must be directly opposite that side", "feedback": "Correct. Each fraction in the sine law pairs a side with the angle sitting directly across from it in the triangle."}, {"text": "They must be adjacent to each other", "feedback": "The angle paired with a side in the sine law is the one opposite it, not one of the two angles touching that side."}, {"text": "The angle must be acute", "feedback": "The sine law works with any angle, acute or obtuse — what matters is that the angle is opposite the paired side, not its size."}]'::jsonb,
 'sine-law-formula-structure'),
('MPM2D', 'trigonometry', 'sine-law', 6, 'Easy',
 'You know two angles of a triangle and one side. Which law should you use to find a missing side?', 0,
 '[{"text": "The sine law", "feedback": "Correct. Knowing two angles and one side gives a complete angle-side pair (the known side and its opposite angle), which the sine law needs."}, {"text": "The cosine law", "feedback": "The cosine law is used when you know two sides and the included angle, or all three sides — not two angles and one side."}, {"text": "The Pythagorean theorem", "feedback": "The Pythagorean theorem only applies to right triangles — there''s no indication this triangle has a right angle."}, {"text": "The quadratic formula", "feedback": "The quadratic formula solves equations of the form ax²+bx+c=0 — it has no role in solving a triangle for a missing side."}]'::jsonb,
 'sine-law-vs-cosine-law-conditions'),
('MPM2D', 'trigonometry', 'sine-law', 7, 'Easy',
 'In a triangle, angle A = 50° and angle B = 70°. What is angle C?', 2,
 '[{"text": "130°", "feedback": "This adds A and B together without subtracting from 180° — the three angles of a triangle sum to 180°."}, {"text": "50°", "feedback": "This just reuses angle A — find C by subtracting both given angles from 180°."}, {"text": "60°", "feedback": "Correct. The three angles of a triangle always sum to 180°, so C = 180° − 50° − 70° = 60°."}, {"text": "120°", "feedback": "This subtracts only one of the two given angles from 180° — both A and B need to be subtracted."}]'::jsonb,
 'triangle-angle-sum'),
('MPM2D', 'trigonometry', 'sine-law', 8, 'Easy',
 'In a triangle with sides a, b, c opposite angles A, B, C, which of these is a correctly written sine law equation?', 1,
 '[{"text": "a/sin B = b/sin A", "feedback": "Each side should be paired with its *own* opposite angle — a with A, and b with B, not swapped."}, {"text": "a/sin A = b/sin B", "feedback": "Correct. The sine law pairs each side with the angle directly opposite it: a with A, and b with B."}, {"text": "sin A/a = sin B/c", "feedback": "This mixes side b''s opposite angle (B) with side c''s own letter — each side should be paired only with its own opposite angle."}, {"text": "a × sin A = b × sin B", "feedback": "The sine law is a ratio (division), not a product — each side is divided by the sine of its opposite angle."}]'::jsonb,
 'sine-law-formula-structure'),
('MPM2D', 'trigonometry', 'sine-law', 9, 'Medium',
 'In a triangle, angle A = 55°, side a = 12, and angle B = 70°. What is the length of side b, to one decimal place?', 3,
 '[{"text": "b ≈ 10.5", "feedback": "This doesn''t come from a÷sin(A) = b÷sin(B) — recheck by cross-multiplying: b = 12 × sin(70°) ÷ sin(55°)."}, {"text": "b ≈ 8.2", "feedback": "This looks like sin(A) and sin(B) were swapped in the ratio — side b should come out larger than side a, since angle B is bigger than angle A."}, {"text": "b ≈ 16.9", "feedback": "This is larger than the correct value — double check that sin(70°) and sin(55°) were placed correctly in the ratio."}, {"text": "b ≈ 13.8", "feedback": "Correct. By the sine law, a÷sin(A) = b÷sin(B), so b = 12 × sin(70°) ÷ sin(55°) ≈ 13.8."}]'::jsonb,
 'sine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'sine-law', 10, 'Medium',
 'In a triangle, angle A = 30°, side a = 8, and angle C = 100°. What is the length of side c, to one decimal place?', 1,
 '[{"text": "c ≈ 4.1", "feedback": "This looks like sin(A) and sin(C) were swapped in the ratio — side c should come out larger than side a, since angle C is much bigger than angle A."}, {"text": "c ≈ 15.8", "feedback": "Correct. By the sine law, a÷sin(A) = c÷sin(C), so c = 8 × sin(100°) ÷ sin(30°) ≈ 15.8."}, {"text": "c ≈ 26.7", "feedback": "This is too large — double check that sin(100°) and sin(30°) were placed correctly in the ratio."}, {"text": "c ≈ 8.0", "feedback": "This just reuses side a — apply the sine law ratio to find the actual value of c."}]'::jsonb,
 'sine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'sine-law', 11, 'Medium',
 'In a triangle, angle B = 45°, side b = 20, and angle A = 60°. What is the length of side a, to one decimal place?', 0,
 '[{"text": "a ≈ 24.5", "feedback": "Correct. By the sine law, a÷sin(A) = b÷sin(B), so a = 20 × sin(60°) ÷ sin(45°) ≈ 24.5."}, {"text": "a ≈ 16.3", "feedback": "This looks like sin(A) and sin(B) were swapped in the ratio — side a should come out larger than side b, since angle A is bigger than angle B."}, {"text": "a ≈ 20.0", "feedback": "This just reuses side b — apply the sine law ratio to find the actual value of a."}, {"text": "a ≈ 30.0", "feedback": "This is too large — double check that sin(60°) and sin(45°) were placed correctly in the ratio."}]'::jsonb,
 'sine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'sine-law', 12, 'Medium',
 'In a triangle, angle C = 80°, side c = 25, and angle B = 35°. What is the length of side b, to one decimal place?', 2,
 '[{"text": "b ≈ 25.0", "feedback": "This just reuses side c — apply the sine law ratio to find the actual value of b."}, {"text": "b ≈ 35.7", "feedback": "This is too large — double check that sin(35°) and sin(80°) were placed correctly in the ratio."}, {"text": "b ≈ 14.6", "feedback": "Correct. By the sine law, b÷sin(B) = c÷sin(C), so b = 25 × sin(35°) ÷ sin(80°) ≈ 14.6."}, {"text": "b ≈ 43.5", "feedback": "This looks like sin(B) and sin(C) were swapped in the ratio — side b should come out smaller than side c, since angle B is smaller than angle C."}]'::jsonb,
 'sine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'sine-law', 13, 'Challenge',
 'In a triangle, side a = 10, angle A = 40°, and side b = 14. What is angle B, to the nearest degree?', 3,
 '[{"text": "B ≈ 29°", "feedback": "This is too small for a triangle where side b (14) is longer than side a (10) — the larger side should be opposite the larger angle."}, {"text": "B ≈ 40°", "feedback": "This just reuses angle A''s value — since sides a and b have different lengths, angles A and B must also differ."}, {"text": "B ≈ 78°", "feedback": "This is too large for this triangle — recheck the ratio sin(B) = b × sin(A) ÷ a before taking the inverse sine."}, {"text": "B ≈ 64°", "feedback": "Correct. By the sine law, sin(B)÷b = sin(A)÷a, so sin(B) = 14 × sin(40°) ÷ 10 ≈ 0.900, giving B ≈ sin⁻¹(0.900) ≈ 64°."}]'::jsonb,
 'sine-law-solve-for-angle'),
('MPM2D', 'trigonometry', 'sine-law', 14, 'Challenge',
 'In a triangle, side a = 15, angle A = 25°, and side c = 20. What is angle C, to the nearest degree?', 1,
 '[{"text": "C ≈ 19°", "feedback": "This is too small — side c (20) is longer than side a (15), so angle C should be larger than angle A (25°), not smaller."}, {"text": "C ≈ 34°", "feedback": "Correct. By the sine law, sin(C)÷c = sin(A)÷a, so sin(C) = 20 × sin(25°) ÷ 15 ≈ 0.563, giving C ≈ sin⁻¹(0.563) ≈ 34°."}, {"text": "C ≈ 25°", "feedback": "This just reuses angle A''s value — since sides a and c have different lengths, angles A and C must also differ."}, {"text": "C ≈ 51°", "feedback": "This is too large for this triangle — recheck the ratio sin(C) = c × sin(A) ÷ a before taking the inverse sine."}]'::jsonb,
 'sine-law-solve-for-angle'),
('MPM2D', 'trigonometry', 'sine-law', 15, 'Challenge',
 'In a triangle, side b = 18, angle B = 55°, and side a = 14. What is angle A, to the nearest degree?', 2,
 '[{"text": "A ≈ 55°", "feedback": "This just reuses angle B''s value — since sides a and b have different lengths, angles A and B must also differ."}, {"text": "A ≈ 51°", "feedback": "Recheck the ratio sin(A) = a × sin(B) ÷ b — this doesn''t quite match that calculation."}, {"text": "A ≈ 40°", "feedback": "Correct. By the sine law, sin(A)÷a = sin(B)÷b, so sin(A) = 14 × sin(55°) ÷ 18 ≈ 0.637, giving A ≈ sin⁻¹(0.637) ≈ 40°."}, {"text": "A ≈ 71°", "feedback": "This is too large for this triangle — side a (14) is shorter than side b (18), so angle A should be smaller than angle B (55°), not larger."}]'::jsonb,
 'sine-law-solve-for-angle'),
('MPM2D', 'trigonometry', 'sine-law', 16, 'Challenge',
 'In a triangle, side c = 22, angle C = 65°, and side a = 17. What is angle A, to the nearest degree?', 0,
 '[{"text": "A ≈ 44°", "feedback": "Correct. By the sine law, sin(A)÷a = sin(C)÷c, so sin(A) = 17 × sin(65°) ÷ 22 ≈ 0.700, giving A ≈ sin⁻¹(0.700) ≈ 44°."}, {"text": "A ≈ 65°", "feedback": "This just reuses angle C''s value — since sides a and c have different lengths, angles A and C must also differ."}, {"text": "A ≈ 84°", "feedback": "This is too large for this triangle — side a (17) is shorter than side c (22), so angle A should be smaller than angle C (65°), not larger."}, {"text": "A ≈ 36°", "feedback": "Recheck the ratio sin(A) = a × sin(C) ÷ c — this doesn''t quite match that calculation."}]'::jsonb,
 'sine-law-solve-for-angle'),
('MPM2D', 'trigonometry', 'sine-law', 17, 'Advanced',
 'In a triangle, angle A = 42°, angle B = 63°, and side a = 9. What is the length of side c, to one decimal place?', 2,
 '[{"text": "c ≈ 9.0", "feedback": "This just reuses side a — angle C needs to be found first, then the sine law applied between a and c."}, {"text": "c ≈ 8.0", "feedback": "This is too small — first find angle C = 180°−42°−63° = 75°, then use it in the sine law ratio."}, {"text": "c ≈ 13.0", "feedback": "Correct. First find angle C = 180° − 42° − 63° = 75°. Then by the sine law, c÷sin(C) = a÷sin(A), so c = 9 × sin(75°) ÷ sin(42°) ≈ 13.0."}, {"text": "c ≈ 16.9", "feedback": "This looks like angle A and angle C were swapped in the ratio — recompute c = a × sin(C) ÷ sin(A) with C = 75°."}]'::jsonb,
 'sine-law-third-angle-first'),
('MPM2D', 'trigonometry', 'sine-law', 18, 'Advanced',
 'In a triangle, angle A = 38°, angle C = 79°, and side c = 30. What is the length of side b, to one decimal place?', 3,
 '[{"text": "b ≈ 30.0", "feedback": "This just reuses side c — angle B needs to be found first, then the sine law applied between b and c."}, {"text": "b ≈ 18.8", "feedback": "This is too small — first find angle B = 180°−38°−79° = 63°, then use it in the sine law ratio with side c."}, {"text": "b ≈ 23.5", "feedback": "Recheck the setup: first find angle B = 180°−38°−79° = 63°, then compute b = c × sin(B) ÷ sin(C)."}, {"text": "b ≈ 27.2", "feedback": "Correct. First find angle B = 180° − 38° − 79° = 63°. Then by the sine law, b÷sin(B) = c÷sin(C), so b = 30 × sin(63°) ÷ sin(79°) ≈ 27.2."}]'::jsonb,
 'sine-law-third-angle-first'),
('MPM2D', 'trigonometry', 'sine-law', 19, 'Advanced',
 'A triangle has side a = 10, side b = 14, and angle A = 40°. How many different triangles are possible?', 1,
 '[{"text": "Exactly one", "feedback": "Check the ambiguous case carefully: the height h = b×sin(A) ≈ 9.0 is less than a (10), which is itself less than b (14) — that combination allows for two triangles, not just one."}, {"text": "Two", "feedback": "Correct. This is the ambiguous (SSA) case: h = b×sin(A) = 14×sin(40°) ≈ 9.0; since h < a (10) < b (14), there are two possible triangles — one with angle B acute, and one with angle B obtuse."}, {"text": "Zero — no triangle is possible", "feedback": "A triangle is possible here — in fact, this exact combination of a shorter given side allows for *two* valid triangles, not zero."}, {"text": "Three", "feedback": "The ambiguous case (SSA) can produce at most two distinct triangles, never three."}]'::jsonb,
 'sine-law-ambiguous-case'),
('MPM2D', 'trigonometry', 'sine-law', 20, 'Advanced',
 'In a triangle, angle A = 55°, angle B = 75°, and side b = 40. Find the triangle''s perimeter, to one decimal place.', 0,
 '[{"text": "≈ 105.6", "feedback": "Correct. First find angle C = 180°−55°−75° = 50°. Then a = 40×sin(55°)÷sin(75°) ≈ 33.9, and c = 40×sin(50°)÷sin(75°) ≈ 31.7; the perimeter is a+b+c ≈ 33.9+40+31.7 ≈ 105.6."}, {"text": "≈ 120.0", "feedback": "This doesn''t come from computing a and c using the sine law with angle C = 50° — recompute both missing sides individually first."}, {"text": "≈ 80.0", "feedback": "This only doubles side b — the other two sides, a and c, need to be found using the sine law before adding everything together."}, {"text": "≈ 91.2", "feedback": "Recheck the value of angle C (180°−55°−75° = 50°) and the resulting side lengths a and c before summing all three sides."}]'::jsonb,
 'sine-law-solve-for-perimeter'),
('MPM2D', 'trigonometry', 'cosine-law', 5, 'Easy',
 'In the cosine law formula c² = a² + b² - 2ab·cos(C), which angle does C represent?', 1,
 '[{"text": "Any one of the triangle''s three angles", "feedback": "C specifically refers to the angle opposite side c — it isn''t an arbitrary choice among the three angles."}, {"text": "The angle between sides a and b, opposite side c", "feedback": "Correct. C is the included angle, sitting between the two known sides a and b, and it''s opposite the side (c) being solved for."}, {"text": "The smallest angle in the triangle", "feedback": "C isn''t defined by being the smallest angle — it''s specifically the angle opposite side c, whatever its size happens to be."}, {"text": "The angle opposite side a", "feedback": "The angle opposite side a is A, not C — C is opposite side c, the side the formula is solving for."}]'::jsonb,
 'cosine-law-formula-structure'),
('MPM2D', 'trigonometry', 'cosine-law', 6, 'Easy',
 'You know all three side lengths of a triangle (SSS). Which law can find a missing angle?', 2,
 '[{"text": "The sine law", "feedback": "The sine law needs a complete angle-side pair (a known angle opposite a known side) to get started — SSS gives no angles at all."}, {"text": "The Pythagorean theorem", "feedback": "The Pythagorean theorem only applies to right triangles — there''s no indication this triangle has a right angle."}, {"text": "The cosine law", "feedback": "Correct. Rearranged to solve for an angle, the cosine law only needs the three side lengths — exactly what SSS provides."}, {"text": "The quadratic formula", "feedback": "The quadratic formula solves equations of the form ax²+bx+c=0 — it has no direct role in finding a triangle''s angle from its three sides."}]'::jsonb,
 'cosine-law-vs-sine-law-conditions'),
('MPM2D', 'trigonometry', 'cosine-law', 7, 'Easy',
 'In the cosine law, when angle C is exactly 90°, what does the formula c² = a² + b² - 2ab·cos(C) simplify to?', 0,
 '[{"text": "The Pythagorean theorem, c² = a² + b²", "feedback": "Correct. Since cos(90°) = 0, the last term (2ab·cos(C)) disappears entirely, leaving exactly the Pythagorean theorem."}, {"text": "c² = a² - b²", "feedback": "This isn''t what happens when cos(90°) = 0 — the whole term 2ab·cos(C) vanishes, not just part of it."}, {"text": "c = a + b", "feedback": "The cosine law works with squared side lengths, not the sides themselves added directly."}, {"text": "c² = 2ab", "feedback": "This keeps only the last term and drops a² and b² entirely — actually the opposite happens: the last term disappears, leaving a²+b²."}]'::jsonb,
 'cosine-law-reduces-to-pythagorean'),
('MPM2D', 'trigonometry', 'cosine-law', 8, 'Easy',
 'Which situation requires the cosine law: knowing all three sides (SSS), or knowing two angles and a side (AAS)?', 0,
 '[{"text": "SSS", "feedback": "Correct. With three sides and no angles, there''s no complete angle-side pair for the sine law — the cosine law (rearranged to solve for an angle) is the tool that works with SSS alone."}, {"text": "AAS", "feedback": "AAS gives a complete angle-side pair (a known angle opposite a known side), which is exactly what the sine law needs — no cosine law required."}, {"text": "Both require the cosine law equally", "feedback": "AAS is a classic sine law situation, since it already provides a matching angle-side pair — only SSS (and SAS) call for the cosine law."}, {"text": "Neither — both need the sine law", "feedback": "SSS has no angles at all, so there''s no angle-side pair to start the sine law with — that''s exactly when the cosine law is needed instead."}]'::jsonb,
 'cosine-law-vs-sine-law-conditions'),
('MPM2D', 'trigonometry', 'cosine-law', 9, 'Medium',
 'In a triangle, a = 8, b = 11, and the angle between them, C = 60°. What is the length of side c, to one decimal place?', 1,
 '[{"text": "c ≈ 13.6", "feedback": "This is too large — recheck the subtraction step in c² = a²+b²−2ab·cos(C); the last term should reduce the sum of squares here."}, {"text": "c ≈ 9.8", "feedback": "Correct. By the cosine law, c² = 8²+11²−2(8)(11)cos(60°) = 185−88 = 97, so c ≈ √97 ≈ 9.8."}, {"text": "c ≈ 19.0", "feedback": "This adds the two given sides directly — the cosine law is needed since they meet at a 60° angle, not a straight line."}, {"text": "c ≈ 97.0", "feedback": "This is c², the value before the final square root — one more step is needed to find c itself."}]'::jsonb,
 'cosine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'cosine-law', 10, 'Medium',
 'In a triangle, a = 9, c = 14, and the angle between them, B = 100°. What is the length of side b, to one decimal place?', 2,
 '[{"text": "b ≈ 16.6", "feedback": "Recheck the subtraction step in b² = a²+c²−2ac·cos(B); with B obtuse, cos(B) is negative, so this term actually adds to a²+c², making b larger than this."}, {"text": "b ≈ 5.0", "feedback": "This is far too small — recompute a²+c²−2ac·cos(100°) carefully, remembering that cos(100°) is negative."}, {"text": "b ≈ 17.9", "feedback": "Correct. By the cosine law, b² = 9²+14²−2(9)(14)cos(100°) = 277−252×cos(100°) ≈ 320.8, so b ≈ √320.8 ≈ 17.9."}, {"text": "b ≈ 23.0", "feedback": "This adds the two given sides directly — the cosine law is needed since they meet at a 100° angle, not a straight line."}]'::jsonb,
 'cosine-law-solve-for-side-obtuse'),
('MPM2D', 'trigonometry', 'cosine-law', 11, 'Medium',
 'In a triangle, b = 12, c = 15, and the angle between them, A = 70°. What is the length of side a, to one decimal place?', 3,
 '[{"text": "a ≈ 27.0", "feedback": "This adds the two given sides directly — the cosine law is needed since they meet at a 70° angle, not a straight line."}, {"text": "a ≈ 3.0", "feedback": "This is too small — recompute b²+c²−2bc·cos(70°) carefully before taking the square root."}, {"text": "a ≈ 369.0", "feedback": "This is a², the value before the final square root — one more step is needed to find a itself."}, {"text": "a ≈ 15.7", "feedback": "Correct. By the cosine law, a² = 12²+15²−2(12)(15)cos(70°) = 369−360×cos(70°) ≈ 245.9, so a ≈ √245.9 ≈ 15.7."}]'::jsonb,
 'cosine-law-solve-for-side'),
('MPM2D', 'trigonometry', 'cosine-law', 12, 'Medium',
 'In a triangle, a = 6, b = 9, and the angle between them, C = 120°. What is the length of side c, to one decimal place?', 1,
 '[{"text": "c ≈ 6.5", "feedback": "Recheck the sign: since C is obtuse, cos(120°) is negative, so the last term −2ab·cos(C) actually *adds* to a²+b², making c larger than a or b."}, {"text": "c ≈ 13.1", "feedback": "Correct. By the cosine law, c² = 6²+9²−2(6)(9)cos(120°) = 117−108×(−0.5) = 117+54 = 171, so c ≈ √171 ≈ 13.1."}, {"text": "c ≈ 15.0", "feedback": "This adds the two given sides directly — the cosine law is needed since they meet at a 120° angle, not a straight line."}, {"text": "c ≈ 3.0", "feedback": "This is far too small — recompute 6²+9²−2(6)(9)cos(120°) carefully."}]'::jsonb,
 'cosine-law-solve-for-side-obtuse'),
('MPM2D', 'trigonometry', 'cosine-law', 13, 'Challenge',
 'A triangle has sides a = 7, b = 9, and c = 11. What is the measure of angle C, to the nearest degree?', 1,
 '[{"text": "C ≈ 41°", "feedback": "This doesn''t match cos⁻¹ of the correct ratio — recompute a²+b²−c² = 49+81−121 = 9 before dividing by 2ab."}, {"text": "C ≈ 86°", "feedback": "Correct. By the cosine law, cos(C) = (a²+b²−c²)÷(2ab) = (49+81−121)÷(2×7×9) = 9÷126 ≈ 0.071, so C ≈ cos⁻¹(0.071) ≈ 86°."}, {"text": "C ≈ 94°", "feedback": "This is close, but recompute a²+b²−c² = 49+81−121 = 9 precisely, then divide by 2ab before taking the inverse cosine."}, {"text": "C ≈ 65°", "feedback": "This doesn''t match cos⁻¹ of the correct ratio — recheck the formula cos(C) = (a²+b²−c²)÷(2ab)."}]'::jsonb,
 'cosine-law-solve-for-angle'),
('MPM2D', 'trigonometry', 'cosine-law', 14, 'Challenge',
 'A triangle has sides a = 6, b = 8, and c = 11. What is the measure of the angle opposite side c, to the nearest degree?', 2,
 '[{"text": "48°", "feedback": "This doesn''t account for the negative value of a²+b²−c² — recompute 36+64−121 = −21 before dividing by 2ab."}, {"text": "77°", "feedback": "Recheck the cosine value: (36+64−121)÷(2×6×8) = −21÷96 ≈ −0.219 — this doesn''t match cos⁻¹ of that value."}, {"text": "103°", "feedback": "Correct. By the cosine law, cos(C) = (6²+8²−11²)÷(2×6×8) = (36+64−121)÷96 = −21÷96 ≈ −0.219, so C ≈ cos⁻¹(−0.219) ≈ 103° — a negative cosine value means this angle is obtuse."}, {"text": "13°", "feedback": "This is far too small — recheck that a²+b²−c² comes out negative here, which means the angle itself must be obtuse (greater than 90°)."}]'::jsonb,
 'cosine-law-solve-for-angle-obtuse'),
('MPM2D', 'trigonometry', 'cosine-law', 15, 'Challenge',
 'A triangle has sides a = 10, b = 12, and c = 15. What is the measure of the smallest angle (opposite the shortest side), to the nearest degree?', 0,
 '[{"text": "A ≈ 42°", "feedback": "Correct. The smallest angle is opposite the shortest side, a = 10. By the cosine law, cos(A) = (b²+c²−a²)÷(2bc) = (144+225−100)÷360 = 269÷360 ≈ 0.747, so A ≈ cos⁻¹(0.747) ≈ 42°."}, {"text": "B ≈ 42°, opposite side b", "feedback": "The smallest angle should be opposite the *shortest* side, which is a = 10, not b = 12."}, {"text": "A ≈ 65°", "feedback": "Recheck the ratio: cos(A) = (b²+c²−a²)÷(2bc) = 269÷360 — this doesn''t match cos⁻¹ of a value leading to 65°."}, {"text": "A ≈ 48°", "feedback": "Recompute 144+225−100 = 269 and divide by 2×12×15 = 360 before taking the inverse cosine."}]'::jsonb,
 'cosine-law-smallest-angle'),
('MPM2D', 'trigonometry', 'cosine-law', 16, 'Challenge',
 'A triangle has sides a = 5, b = 7, and c = 9. What is the measure of the largest angle (opposite the longest side), to the nearest degree?', 3,
 '[{"text": "C ≈ 84°", "feedback": "Recheck the sign: a²+b²−c² = 25+49−81 = −7, which is negative — that means the angle itself is obtuse, greater than 90°."}, {"text": "A ≈ 96°, opposite side a", "feedback": "The largest angle should be opposite the *longest* side, which is c = 9, not a = 5."}, {"text": "C ≈ 90°, since it''s a right triangle", "feedback": "Check whether a²+b² actually equals c²: 25+49 = 74, not 81 — this isn''t a right triangle."}, {"text": "C ≈ 96°", "feedback": "Correct. The largest angle is opposite the longest side, c = 9. By the cosine law, cos(C) = (a²+b²−c²)÷(2ab) = (25+49−81)÷70 = −7÷70 = −0.1, so C ≈ cos⁻¹(−0.1) ≈ 96°."}]'::jsonb,
 'cosine-law-largest-angle'),
('MPM2D', 'trigonometry', 'cosine-law', 17, 'Advanced',
 'Two hikers leave camp together, one walking 8 km on one path, the other walking 11 km on a path that makes a 75° angle with the first. How far apart are they, to one decimal place?', 2,
 '[{"text": "19.0 km", "feedback": "This just adds the two distances directly — since the two paths diverge at a 75° angle rather than continuing in a straight line, the cosine law is needed."}, {"text": "9.6 km", "feedback": "This is too small for two paths diverging at 75° — recheck the full cosine law expression before taking the square root."}, {"text": "11.8 km", "feedback": "Correct. By the cosine law, distance² = 8²+11²−2(8)(11)cos(75°) ≈ 139.4, so distance ≈ √139.4 ≈ 11.8 km."}, {"text": "13.4 km", "feedback": "This looks like the angle was treated as obtuse (using a negative cosine) — but 75° is acute, so cos(75°) is positive here."}]'::jsonb,
 'cosine-law-navigation-application'),
('MPM2D', 'trigonometry', 'cosine-law', 18, 'Advanced',
 'A triangular park has two sides of length 120 m and 150 m, with an included angle of 100°. Find the length of the third side, to the nearest metre.', 1,
 '[{"text": "270 m", "feedback": "This just adds the two given sides directly — the cosine law is needed since they meet at a 100° angle, not a straight line."}, {"text": "208 m", "feedback": "Correct. By the cosine law, third side² = 120²+150²−2(120)(150)cos(100°) ≈ 43,151, so the third side ≈ √43,151 ≈ 208 m."}, {"text": "184 m", "feedback": "This looks like the angle 100° was treated as acute (using a positive cosine) — but 100° is obtuse, so cos(100°) is actually negative."}, {"text": "30 m", "feedback": "This subtracts the two given sides instead of using the full cosine law expression."}]'::jsonb,
 'cosine-law-application'),
('MPM2D', 'trigonometry', 'cosine-law', 19, 'Advanced',
 'A surveyor measures a triangular lot with sides 45 m, 60 m, and 75 m. What is the largest angle, to the nearest degree?', 3,
 '[{"text": "It cannot be a right angle, since 45-60-75 aren''t a Pythagorean triple", "feedback": "Check this carefully: 45² + 60² = 2025+3600 = 5625, and 75² = 5625 — these are actually equal, meaning it IS a right angle."}, {"text": "85°, opposite the side of 60 m", "feedback": "The largest angle is opposite the *longest* side (75 m), not the side of 60 m — and its actual measure comes out to a round number."}, {"text": "The angle can''t be determined without more information", "feedback": "The three side lengths (SSS) are exactly enough information to find any angle in a triangle, using the cosine law."}, {"text": "90°, opposite the side of 75 m", "feedback": "Correct. The largest angle is opposite the longest side (75 m). Checking: 45²+60² = 2025+3600 = 5625 = 75², so this is a right triangle (a 3-4-5 triangle scaled by 15), and the angle opposite 75 m is exactly 90°."}]'::jsonb,
 'cosine-law-recognize-right-triangle'),
('MPM2D', 'trigonometry', 'cosine-law', 20, 'Advanced',
 'In triangle ABC, a = 10, b = 14, and angle C = 50°. Find side c, then use it to find angle A, both to one decimal place / nearest degree.', 0,
 '[{"text": "c ≈ 10.8, A ≈ 45°", "feedback": "Correct. First, c² = 10²+14²−2(10)(14)cos(50°) ≈ 116, so c ≈ 10.8. Then by the sine law, sin(A) = 10×sin(50°)÷10.8 ≈ 0.709, giving A ≈ 45°."}, {"text": "c ≈ 4.0, A ≈ 45°", "feedback": "The value of A is right, but recompute c using the full cosine law expression, c² = 10²+14²−2(10)(14)cos(50°), before taking the square root."}, {"text": "c ≈ 10.8, A ≈ 65°", "feedback": "The value of c is right, but recheck the sine law step: sin(A) = a×sin(C)÷c, using the correct value of c you just found."}, {"text": "c ≈ 24.0, A ≈ 25°", "feedback": "This adds the two given sides directly for c — the cosine law is needed since they meet at a 50° angle, not a straight line."}]'::jsonb,
 'cosine-then-sine-law-two-step'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 5, 'Easy',
 'An acute triangle has three angles that are all ___ 90°.', 1,
 '[{"text": "greater than", "feedback": "Angles greater than 90° describe an obtuse triangle, not an acute one."}, {"text": "less than", "feedback": "Correct. Every angle in an acute triangle measures less than 90°."}, {"text": "equal to", "feedback": "A triangle with an angle equal to 90° is a right triangle, not an acute one."}, {"text": "a multiple of", "feedback": "There''s no requirement that the angles be multiples of 90° — only that each one is strictly less than 90°."}]'::jsonb,
 'acute-triangle-definition'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 6, 'Easy',
 'Which set of angles could belong to an acute triangle: 50°, 60°, 70° or 40°, 40°, 100°?', 0,
 '[{"text": "50°, 60°, 70°", "feedback": "Correct. All three angles are less than 90°, and they sum to 180°, so this is a valid acute triangle."}, {"text": "40°, 40°, 100°", "feedback": "The 100° angle is greater than 90°, which makes this an obtuse triangle, not an acute one."}, {"text": "Both sets could be acute triangles", "feedback": "The second set includes a 100° angle, which is greater than 90° — that makes it obtuse, not acute."}, {"text": "Neither set is a valid triangle", "feedback": "Both sets of angles actually sum to 180°, so both describe valid triangles — just not both acute ones."}]'::jsonb,
 'acute-triangle-identify-from-angles'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 7, 'Easy',
 'Given only the three side lengths (SSS) of an acute triangle, which law would you use to find one of its angles?', 2,
 '[{"text": "The sine law", "feedback": "The sine law needs a complete angle-side pair (a known angle opposite a known side) to get started — SSS gives no angles at all."}, {"text": "The Pythagorean theorem", "feedback": "The Pythagorean theorem only applies to right triangles — an acute triangle has no right angle."}, {"text": "The cosine law", "feedback": "Correct. Rearranged to solve for an angle, the cosine law only needs the three side lengths — exactly what SSS provides."}, {"text": "The quadratic formula", "feedback": "The quadratic formula solves equations of the form ax²+bx+c=0 — it has no direct role in finding a triangle''s angle from its three sides."}]'::jsonb,
 'acute-triangle-tool-choice'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 8, 'Easy',
 'True or false: every equilateral triangle is an acute triangle.', 0,
 '[{"text": "True", "feedback": "Correct. An equilateral triangle''s three angles are always equal, and since they sum to 180°, each one is exactly 60° — well under 90°, making it acute."}, {"text": "False, because equilateral triangles have no defined angles", "feedback": "Every triangle, equilateral or not, has three well-defined interior angles that sum to 180°."}, {"text": "False, because equilateral triangles are always right triangles", "feedback": "A right triangle needs one angle of exactly 90° — an equilateral triangle''s angles are all 60°, nowhere near 90°."}, {"text": "It depends on the side lengths", "feedback": "An equilateral triangle''s angles are always 60°-60°-60°, regardless of how long its sides are — so it''s always acute."}]'::jsonb,
 'acute-triangle-equilateral-special-case'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 9, 'Medium',
 'A triangular sail has two sides of 4 m and 6 m, with an included angle of 65°. Find the length of the third side, to one decimal place.', 2,
 '[{"text": "10.0 m", "feedback": "This just adds the two given sides directly — the cosine law is needed since they meet at a 65° angle, not a straight line."}, {"text": "2.0 m", "feedback": "This subtracts the two given sides instead of using the full cosine law expression."}, {"text": "5.6 m", "feedback": "Correct. By the cosine law, third side² = 4²+6²−2(4)(6)cos(65°) ≈ 31.7, so the third side ≈ √31.7 ≈ 5.6 m."}, {"text": "31.7 m", "feedback": "This is the third side squared, the value before the final square root — one more step is needed."}]'::jsonb,
 'acute-triangle-cosine-law-application'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 10, 'Medium',
 'A triangular plot has two sides of 9 m and 13 m, with an included angle of 40°. Find the length of the third side, to one decimal place.', 1,
 '[{"text": "22.0 m", "feedback": "This just adds the two given sides directly — the cosine law is needed since they meet at a 40° angle, not a straight line."}, {"text": "8.4 m", "feedback": "Correct. By the cosine law, third side² = 9²+13²−2(9)(13)cos(40°) ≈ 70.7, so the third side ≈ √70.7 ≈ 8.4 m."}, {"text": "4.0 m", "feedback": "This subtracts the two given sides instead of using the full cosine law expression."}, {"text": "70.7 m", "feedback": "This is the third side squared, the value before the final square root — one more step is needed."}]'::jsonb,
 'acute-triangle-cosine-law-application'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 11, 'Medium',
 'In acute triangle DEF, angle D = 55°, side d = 18, and angle E = 65°. Find the length of side e, to one decimal place.', 3,
 '[{"text": "e ≈ 18.0", "feedback": "This just reuses side d — apply the sine law ratio to find the actual value of e."}, {"text": "e ≈ 15.4", "feedback": "This looks like sin(D) and sin(E) were swapped in the ratio — side e should come out larger than side d, since angle E is bigger than angle D."}, {"text": "e ≈ 22.4", "feedback": "This is too large — double check that sin(65°) and sin(55°) were placed correctly in the ratio."}, {"text": "e ≈ 19.9", "feedback": "Correct. By the sine law, d÷sin(D) = e÷sin(E), so e = 18 × sin(65°) ÷ sin(55°) ≈ 19.9."}]'::jsonb,
 'acute-triangle-sine-law-application'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 12, 'Medium',
 'In an acute triangle, two angles are 48° and 72°, and the side opposite the 48° angle is 10. Find the side opposite the third angle, to one decimal place.', 0,
 '[{"text": "11.7", "feedback": "Correct. The third angle is 180°−48°−72° = 60°. By the sine law, 10÷sin(48°) = x÷sin(60°), so x = 10 × sin(60°) ÷ sin(48°) ≈ 11.7."}, {"text": "10.0", "feedback": "This just reuses the given side — the third angle (60°) and the sine law are still needed to find its opposite side."}, {"text": "15.0", "feedback": "This doesn''t come from the sine law ratio — recompute the third angle (180°−48°−72°=60°) and apply 10×sin(60°)÷sin(48°)."}, {"text": "8.5", "feedback": "This looks like sin(48°) and sin(60°) were swapped in the ratio — the third side should come out larger than 10, since 60° is bigger than 48°."}]'::jsonb,
 'acute-triangle-sine-law-third-side'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 13, 'Challenge',
 'A triangular garden has sides of 14 m and 18 m, with an included angle of 55°. Find its perimeter, to one decimal place.', 1,
 '[{"text": "47.0 m", "feedback": "This adds the two given sides plus a rounded guess for the third — recompute the third side using the full cosine law expression."}, {"text": "47.2 m", "feedback": "Correct. By the cosine law, the third side² = 14²+18²−2(14)(18)cos(55°) ≈ 230.9, so the third side ≈ 15.2 m; the perimeter is 14+18+15.2 ≈ 47.2 m."}, {"text": "32.0 m", "feedback": "This only adds the two given sides — the third side, found using the cosine law, still needs to be included."}, {"text": "64.2 m", "feedback": "This looks like the third side was added twice, or another arithmetic slip occurred — recompute 14+18+(third side) carefully."}]'::jsonb,
 'acute-triangle-perimeter-application'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 14, 'Challenge',
 'A triangle has sides 11, 13, and 16. Find its smallest angle, to the nearest degree.', 2,
 '[{"text": "53°", "feedback": "This doesn''t match cos⁻¹ of the correct ratio for the angle opposite the shortest side (11) — recheck the cosine law setup."}, {"text": "61°", "feedback": "Recheck which side is shortest — the smallest angle is opposite the shortest side, 11, not one of the other two."}, {"text": "43°", "feedback": "Correct. The smallest angle is opposite the shortest side, 11. By the cosine law, cos(A) = (13²+16²−11²)÷(2×13×16) = (169+256−121)÷416 = 304÷416 ≈ 0.731, so A ≈ cos⁻¹(0.731) ≈ 43°."}, {"text": "76°", "feedback": "This is too large for the angle opposite the shortest side — recheck the cosine law ratio (13²+16²−11²)÷(2×13×16)."}]'::jsonb,
 'acute-triangle-smallest-angle'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 15, 'Challenge',
 'In a triangle, a = 9, b = 12, and angle C = 48°. Find side c, then use it to find angle B (both to one decimal place / nearest degree).', 3,
 '[{"text": "c ≈ 21.0, B ≈ 34°", "feedback": "This adds the two given sides directly for c — the cosine law is needed since they meet at a 48° angle, not a straight line."}, {"text": "c ≈ 3.0, B ≈ 84°", "feedback": "The value of B is close, but recompute c using the full cosine law expression, c² = 9²+12²−2(9)(12)cos(48°), before taking the square root."}, {"text": "c ≈ 9.0, B ≈ 48°", "feedback": "This just reuses side a for c and angle C for B — both quantities need to be freshly computed using the cosine law and then the sine law."}, {"text": "c ≈ 9.0, B ≈ 84°", "feedback": "Correct. First, c² = 9²+12²−2(9)(12)cos(48°) ≈ 80.5, so c ≈ 9.0. Then by the sine law, sin(B) = 12×sin(48°)÷9.0 ≈ 0.994, giving B ≈ 84°."}]'::jsonb,
 'acute-triangle-cosine-then-sine'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 16, 'Challenge',
 'A triangle has sides of 10 and 14, with an included angle of 40°. Find its area, to one decimal place.', 0,
 '[{"text": "45.0", "feedback": "Correct. Area = ½ × 10 × 14 × sin(40°) ≈ 45.0."}, {"text": "70.0", "feedback": "This is ½ × 10 × 14 without the sine of the included angle — the angle between the two sides still needs to be factored in."}, {"text": "140.0", "feedback": "This multiplies the two sides without the ½ factor or the sine of the included angle."}, {"text": "107.1", "feedback": "This uses cos(40°) instead of sin(40°) — the area formula for two sides and an included angle uses sine, not cosine."}]'::jsonb,
 'acute-triangle-area-formula'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 17, 'Advanced',
 'In a triangle, a = 20, b = 25, and angle C = 35°. Find side c, then use it to find angle B (both to one decimal place / nearest degree).', 2,
 '[{"text": "c ≈ 45.0, B ≈ 35°", "feedback": "This adds the two given sides directly for c — the cosine law is needed since they meet at a 35° angle, not a straight line."}, {"text": "c ≈ 5.0, B ≈ 88°", "feedback": "The value of B is close, but recompute c using the full cosine law expression, c² = 20²+25²−2(20)(25)cos(35°), before taking the square root."}, {"text": "c ≈ 14.3, B ≈ 88°", "feedback": "Correct. First, c² = 20²+25²−2(20)(25)cos(35°) ≈ 205.8, so c ≈ 14.3. Then by the sine law, sin(B) = 25×sin(35°)÷14.3 ≈ 0.9997, giving B ≈ 88°."}, {"text": "c ≈ 14.3, B ≈ 35°", "feedback": "This just reuses angle C''s value for B — angle B still needs to be freshly computed using the sine law with the newly-found side c."}]'::jsonb,
 'acute-triangle-cosine-then-sine'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 18, 'Advanced',
 'A triangle has sides a = 15 and b = 20, and its area is 120. Find the acute angle C between them, to the nearest degree.', 1,
 '[{"text": "C ≈ 37°", "feedback": "This doesn''t match sin⁻¹ of the correct ratio — recompute sin(C) = (2×Area)÷(a×b) = 240÷300 first."}, {"text": "C ≈ 53°", "feedback": "Correct. Using Area = ½ab·sin(C), 120 = ½(15)(20)sin(C) gives sin(C) = 240÷300 = 0.8, so C = sin⁻¹(0.8) ≈ 53° (taking the acute solution)."}, {"text": "C ≈ 80°", "feedback": "This is too large — recompute sin(C) = (2×120)÷(15×20) = 0.8, then take the inverse sine for the acute angle."}, {"text": "C ≈ 127°", "feedback": "This is the obtuse solution to sin(C) = 0.8 — since the triangle is described as acute, take the acute angle instead, sin⁻¹(0.8) ≈ 53°."}]'::jsonb,
 'acute-triangle-area-solve-for-angle'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 19, 'Advanced',
 'A triangle has two sides of 12 and 16, with an included angle of 55°. Find both its area and its perimeter, each to one decimal place.', 3,
 '[{"text": "Area ≈ 78.6, perimeter ≈ 28.0", "feedback": "The area is right, but the perimeter is missing the third side — find it using the cosine law before adding it to 12+16."}, {"text": "Area ≈ 96.0, perimeter ≈ 41.4", "feedback": "Recompute the area using ½ × 12 × 16 × sin(55°), not simply ½ × 12 × 16 without the sine factor."}, {"text": "Area ≈ 78.6, perimeter ≈ 40.0", "feedback": "The area is right, but recompute the third side using the cosine law more precisely before adding it to 12+16."}, {"text": "Area ≈ 78.6, perimeter ≈ 41.4", "feedback": "Correct. Area = ½(12)(16)sin(55°) ≈ 78.6; the third side is √(12²+16²−2(12)(16)cos(55°)) ≈ 13.4, so the perimeter is 12+16+13.4 ≈ 41.4."}]'::jsonb,
 'acute-triangle-area-and-perimeter'),
('MPM2D', 'trigonometry', 'acute-triangle-applications', 20, 'Advanced',
 'A triangle has two sides of 13 and 18, with an included angle of 62° between them. Find the height measured from the vertex opposite the 18 m side, to one decimal place.', 0,
 '[{"text": "11.5 m", "feedback": "Correct. The height from the vertex between the 13 m side and the 62° angle, measured perpendicular to the 18 m side, is 13×sin(62°) ≈ 11.5 m."}, {"text": "15.9 m", "feedback": "This uses cos(62°) instead of sin(62°) — the height perpendicular to the base uses the sine of the angle at the vertex."}, {"text": "18.0 m", "feedback": "This just reuses the base length — the height is a separate perpendicular measurement, found using 13×sin(62°)."}, {"text": "6.1 m", "feedback": "This looks like a different combination of the given values — recompute 13×sin(62°) directly."}]'::jsonb,
 'acute-triangle-height-application');

-- ===========================================================================
-- MCR3U
-- ===========================================================================

delete from public.questions where course_code = 'MCR3U';

insert into public.questions
  (course_code, unit_code, subtopic_code, sort_order, difficulty,
   prompt, correct_index, options, misconception_tag)
values
('MCR3U', 'sequences-and-series', 'arithmetic-sequences', 1, 'Easy',
 'Find the next term:   3, 7, 11, 15, ...', 2,
 '[
   {"text": "17", "feedback": "Check the pattern between terms — each one increases by the same fixed amount."},
   {"text": "18", "feedback": "Close, but recheck the common difference between consecutive terms."},
   {"text": "19", "feedback": "Correct. This is arithmetic with common difference 4, so the next term is 15 + 4 = 19."},
   {"text": "20", "feedback": "This adds 5 rather than the actual difference between the given terms."}
 ]'::jsonb,
 'arithmetic-common-difference'),
('MCR3U', 'sequences-and-series', 'arithmetic-sequences', 2, 'Easy',
 'Find the 10th term of the arithmetic sequence with first term 5 and common difference 3.', 0,
 '[
   {"text": "32", "feedback": "Correct. tₙ = a + (n − 1)d = 5 + 9(3) = 5 + 27 = 32."},
   {"text": "35", "feedback": "This multiplies by 10 rather than 9 — the formula uses (n − 1), not n."},
   {"text": "27", "feedback": "This is only the added part, 9 × 3. The first term of 5 still needs to be included."},
   {"text": "38", "feedback": "This adds one extra step of 3. Check that (n − 1) uses 9, not 10 or 11."}
 ]'::jsonb,
 'nth-term-off-by-one'),
('MCR3U', 'sequences-and-series', 'arithmetic-series', 1, 'Medium',
 'Find the sum of the first 20 terms of the arithmetic sequence 2, 5, 8, 11, ...', 1,
 '[
   {"text": "590", "feedback": "Close — recheck the 20th term: a + 19d = 2 + 57 = 59, not a smaller value."},
   {"text": "610", "feedback": "Correct. Using Sₙ = n/2 × (2a + (n−1)d) = 10 × (4 + 57) = 10 × 61 = 610."},
   {"text": "1220", "feedback": "This looks like the sum was doubled. Recheck the n/2 factor at the start of the formula."},
   {"text": "600", "feedback": "Very close, but recompute (n − 1)d = 19 × 3 = 57 exactly before adding 2a."}
 ]'::jsonb,
 'arithmetic-series-sum'),
('MCR3U', 'sequences-and-series', 'geometric-sequences', 1, 'Easy',
 'Is the sequence   4, 8, 16, 32, ...   arithmetic or geometric?', 1,
 '[
   {"text": "Arithmetic", "feedback": "Check the differences between terms: 8 − 4 = 4, but 16 − 8 = 8. They are not the same, so it is not arithmetic."},
   {"text": "Geometric", "feedback": "Correct. Each term is double the one before it, a constant ratio of 2, which is what defines a geometric sequence."},
   {"text": "Neither", "feedback": "There is a clear, consistent pattern here — check whether dividing consecutive terms gives the same result each time."},
   {"text": "Both", "feedback": "A sequence can only be one or the other unless it has just one or two terms. Check the ratio between consecutive terms."}
 ]'::jsonb,
 'arithmetic-vs-geometric'),
('MCR3U', 'sequences-and-series', 'geometric-sequences', 2, 'Medium',
 'Find the 6th term of the geometric sequence with first term 3 and common ratio 2.', 2,
 '[
   {"text": "18", "feedback": "This adds 3 six times rather than multiplying repeatedly, which is the arithmetic pattern rather than geometric."},
   {"text": "48", "feedback": "This uses one fewer multiplication than needed. Check that the exponent is n − 1, not n − 2."},
   {"text": "96", "feedback": "Correct. tₙ = ar^(n−1) = 3 × 2⁵ = 3 × 32 = 96."},
   {"text": "192", "feedback": "This uses one extra multiplication by 2. The exponent should be n − 1 = 5, not 6."}
 ]'::jsonb,
 'geometric-nth-term'),
('MCR3U', 'sequences-and-series', 'geometric-series', 1, 'Medium',
 'Find the sum of the first 5 terms of the geometric sequence 2, 6, 18, 54, ...', 3,
 '[
   {"text": "80", "feedback": "This looks like the terms were simply added up to the 4th term. There is a 5th term still to include."},
   {"text": "150", "feedback": "Check the ratio used in the formula — it should be 3, matching how each term triples."},
   {"text": "486", "feedback": "That is the value of the 6th term, not the sum of the first 5 terms."},
   {"text": "242", "feedback": "Correct. Sₙ = a(rⁿ − 1)/(r − 1) = 2(3⁵ − 1)/(3 − 1) = 2(242)/2 = 242."}
 ]'::jsonb,
 'geometric-series-sum'),
('MCR3U', 'sequences-and-series', 'geometric-series', 2, 'Hard',
 'Find the sum to infinity of   6 + 3 + 1.5 + 0.75 + ...', 0,
 '[
   {"text": "12", "feedback": "Correct. The ratio is 0.5, and since it is between −1 and 1 the sum converges: S = a/(1 − r) = 6/0.5 = 12."},
   {"text": "6", "feedback": "This is just the first term. The infinite sum accounts for every term added afterwards as well."},
   {"text": "18", "feedback": "Check the formula a/(1 − r) directly — divide 6 by 0.5 rather than multiplying."},
   {"text": "Infinite", "feedback": "The sum only diverges when the size of the ratio is 1 or more. Here the ratio is 0.5, which is small enough for the sum to settle."}
 ]'::jsonb,
 'infinite-series-ratio'),
('MCR3U', 'sequences-and-series', 'arithmetic-sequences', 3, 'Easy',
 'A sequence is defined by t₁ = 5, tₙ = tₙ₋₁ + 4. What is t₄?', 1,
 '[
   {"text": "13", "feedback": "This looks like only two steps of adding 4 were applied. Starting from t₁, three additions are needed to reach t₄."},
   {"text": "17", "feedback": "Correct. t₂ = 9, t₃ = 13, t₄ = 17 — three additions of 4 starting from 5."},
   {"text": "20", "feedback": "This applies four additions of 4, but t₁ is already the first term, so only three more steps are needed."},
   {"text": "9", "feedback": "This is only t₂. Continue applying the rule two more times to reach t₄."}
 ]'::jsonb,
 'recursive-sequence'),
('MCR3U', 'sequences-and-series', 'arithmetic-sequences', 4, 'Medium',
 'The interior angles of polygons form a sequence: triangle 180°, quadrilateral 360°, pentagon 540°. What is the formula for an n-sided polygon?', 2,
 '[
   {"text": "180n", "feedback": "Test this on the triangle: 180 × 3 = 540, but a triangle only has 180° total."},
   {"text": "360(n − 2)", "feedback": "Test with n = 3: 360(1) = 360, which is double what a triangle actually has."},
